INSERT INTO `print_templates` (`id`, `created_at`, `name`, `product_label_type_id`, `width_mm`, `height_mm`, `variant`, `html_source`, `is_active`, `is_default`) VALUES
(2, '2026-09-16 08:32:30', 'Fikko Cena Vel.2', 4, 133.00, 38.00, 'always', '<style>\n    @page { margin: 0; }\n    html, body { margin: 0; padding: 0; font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif; background: #fff; color: #111; -webkit-font-smoothing: antialiased; }\n    * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n\n    .fikko-vel2 {\n        box-sizing: border-box;\n        position: relative;\n        width: 133mm;\n        height: 38mm;\n        border: 0.4mm dashed #111;\n        background: #fff;\n        color: #111;\n        overflow: hidden;\n        font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif;\n    }\n\n    /* Left logo / brand column (24mm x 38mm) */\n    .vel2-logo-col {\n        position: absolute;\n        top: 0;\n        left: 0;\n        width: 24mm;\n        height: 38mm;\n        border-right: 0.4mm dashed #111;\n        text-align: center;\n        padding: 1.5mm 1mm;\n    }\n    .vel2-logo-img {\n        width: 14mm;\n        height: 11mm;\n        object-fit: contain;\n        display: block;\n        margin: 0 auto;\n        filter: grayscale(1) contrast(1.15);\n    }\n    .vel2-logo-divider {\n        width: 100%;\n        margin: 1.2mm auto 1.2mm auto;\n        border-top: 0.3mm dashed #111;\n    }\n    .vel2-brand-text {\n        text-align: center;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 4.4mm;\n        line-height: 1.05;\n        color: #111;\n    }\n\n    /* Right main content column (109mm x 38mm) */\n    .vel2-content-col {\n        position: absolute;\n        top: 0;\n        left: 27.5mm;\n        width: 103mm;\n        height: 38mm;\n        padding: 0.8mm 1mm 0.6mm 1mm;\n    }\n\n    /* 1. Product Name */\n    .vel2-prod-name {\n        text-align: center;\n        font-size: 3.2mm;\n        font-weight: 400;\n        line-height: 1.1;\n        overflow: hidden;\n        white-space: nowrap;\n        height: 3.6mm;\n        padding-top: 0.2mm;\n    }\n\n    /* 2. Meta row (Origin, Note1, More species) */\n    .vel2-meta-table {\n        width: 100%;\n        border-collapse: collapse;\n        margin-top: 0.4mm;\n    }\n    .vel2-meta-left {\n        width: 50mm;\n        vertical-align: top;\n        text-align: left;\n    }\n    .vel2-meta-center {\n        vertical-align: top;\n        text-align: center;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.6mm;\n        line-height: 1.1;\n        white-space: nowrap;\n    }\n    .vel2-meta-right {\n        width: 10mm;\n    }\n\n    .vel2-more-species {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.6mm;\n        line-height: 1.1;\n        margin-bottom: 0.2mm;\n    }\n    .vel2-origin-row {\n        display: table;\n        white-space: nowrap;\n    }\n    .vel2-origin-label-cell {\n        display: table-cell;\n        vertical-align: middle;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.2mm;\n        padding-right: 1mm;\n    }\n    .vel2-origin-flag-cell {\n        display: table-cell;\n        vertical-align: middle;\n        width: 4.2mm;\n    }\n    .vel2-origin-flag-img {\n        width: 3.6mm;\n        height: 2.4mm;\n        display: block;\n        border: 0.2mm solid #111;\n    }\n    .vel2-origin-name-cell {\n        display: table-cell;\n        vertical-align: middle;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.2mm;\n        padding-left: 1mm;\n    }\n\n    /* 3. Main Price & Discount Table - NO vertical divider */\n    .vel2-price-table {\n        width: 100%;\n        border-collapse: collapse;\n        margin-top: 0.4mm;\n    }\n    .vel2-price-left {\n        width: 50mm;\n        vertical-align: middle;\n        text-align: center;\n        padding-right: 1.5mm;\n    }\n    .vel2-price-right {\n        vertical-align: middle;\n        text-align: left;\n        padding-left: 2mm;\n    }\n\n    /* Nejnižší cena za 30 dní */\n    .vel2-lowest-row {\n        white-space: nowrap;\n        text-align: center;\n    }\n    .vel2-lowest-label {\n        display: inline-block;\n        vertical-align: middle;\n        font-size: 2.2mm;\n        line-height: 1.2;\n        letter-spacing: 0.04em;\n        text-transform: uppercase;\n        font-weight: 700;\n        color: #111;\n        text-align: right;\n        margin-right: 1.5mm;\n    }\n    .vel2-lowest-val-box {\n        position: relative;\n        display: inline-block;\n        vertical-align: middle;\n    }\n    .vel2-lowest-val {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 5.5mm;\n        line-height: 1;\n        color: #111;\n    }\n    .vel2-strike-wrap {\n        position: absolute;\n        left: 0;\n        top: 0;\n        width: 0;\n        height: 0;\n        overflow: visible;\n        display: inline-block;\n    }\n    .vel2-strike-img {\n        position: absolute;\n        left: -1mm;\n        top: 3.0mm;\n        height: 2.8mm;\n    }\n\n    /* Ušetříte brush badge */\n    .vel2-save-box {\n        position: relative;\n        width: 44mm;\n        height: 4.8mm;\n        margin-top: 0.6mm;\n        margin-left: auto;\n        margin-right: auto;\n        transform: rotate(-1.2deg);\n        color: #fff;\n    }\n    .vel2-save-brush {\n        position: absolute;\n        top: 0;\n        left: 0;\n        width: 44mm;\n        height: 4.8mm;\n        z-index: 0;\n    }\n    .vel2-save-table {\n        position: relative;\n        z-index: 1;\n        width: 44mm;\n        height: 4.8mm;\n        border-collapse: collapse;\n        margin: 0 auto;\n    }\n    .vel2-save-copy-cell {\n        vertical-align: middle;\n        text-align: right;\n        font-size: 2.4mm;\n        letter-spacing: 0.08em;\n        text-transform: uppercase;\n        font-weight: 700;\n        white-space: nowrap;\n        padding-left: 2.5mm;\n        color: #fff;\n    }\n    .vel2-save-val-cell {\n        vertical-align: middle;\n        text-align: center;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 4.5mm;\n        line-height: 1;\n        white-space: nowrap;\n        padding: 0 1.5mm;\n        color: #fff;\n    }\n\n    /* Naše cena */\n    .vel2-our-label {\n        font-size: 2.2mm;\n        letter-spacing: 0.08em;\n        text-transform: uppercase;\n        font-weight: 700;\n        margin-bottom: 0.2mm;\n        margin-left: 6mm;\n    }\n    .vel2-main-price-box {\n        white-space: nowrap;\n        margin-left: 2mm;\n    }\n    .vel2-price-major {\n        display: inline-block;\n        vertical-align: top;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 16.5mm;\n        line-height: 0.85;\n    }\n    .vel2-price-minor-col {\n        display: inline-block;\n        vertical-align: top;\n        text-align: left;\n        padding-top: 0.3mm;\n        margin-left: 1mm;\n    }\n    .vel2-price-minor {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 8.5mm;\n        line-height: 0.9;\n    }\n    .vel2-price-currency {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 3.4mm;\n        line-height: 0.9;\n        white-space: nowrap;\n        margin-top: 0.3mm;\n    }\n\n    /* 4. Bottom row (EAN, Note 3, Unit price) - Absolute at bottom */\n    .vel2-bottom-box {\n        position: absolute;\n        left: 28mm;\n        right: 2.5mm;\n        bottom: 1.8mm;\n        width: 102.5mm;\n    }\n    .vel2-bottom-table {\n        width: 100%;\n        border-collapse: collapse;\n    }\n    .vel2-bottom-ean {\n        vertical-align: bottom;\n        text-align: left;\n        font-size: 2.2mm;\n        font-weight: 600;\n        white-space: nowrap;\n    }\n    .vel2-bottom-note3 {\n        vertical-align: bottom;\n        text-align: center;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.2mm;\n        line-height: 1.1;\n        white-space: nowrap;\n    }\n    .vel2-bottom-unit {\n        vertical-align: bottom;\n        text-align: right;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.2mm;\n        white-space: nowrap;\n    }\n\n    /* 3-digit price scaling (e.g. 199 Kč) */\n    .price-digits-3 .vel2-price-major { font-size: 14mm; }\n    .price-digits-3 .vel2-price-minor { font-size: 7.2mm; }\n    .price-digits-3 .vel2-price-currency { font-size: 2.9mm; margin-top: 0.2mm; }\n    .price-digits-3 .vel2-our-label { margin-left: 3mm; }\n    .price-digits-3 .vel2-main-price-box { margin-left: 0.5mm; }\n    .price-digits-3 .vel2-lowest-val { font-size: 4.8mm; }\n    .price-digits-3 .vel2-price-left { width: 48mm; }\n</style>\n\n{var $vel2Classes = ($priceDigits >= 3 ? \'price-digits-3\' : \'\')}\n{var $logoMarkup = \'<img class=\"vel2-logo-img\" src=\"\' . $logoDataUri . \'\" alt=\"Fikko market\">\'}\n{var $flagMarkup = $flagIconDataUri ? \'<img class=\"vel2-origin-flag-img\" src=\"\' . $flagIconDataUri . \'\" alt=\"\">\' : \'\'}\n{var $brushMarkup = \'<img class=\"vel2-save-brush\" src=\"\' . $brushDataUri . \'\" alt=\"\">\'}\n{var $strikeWidth = (strlen($basePriceText) <= 4 ? \'18mm\' : (strlen($basePriceText) <= 5 ? \'23mm\' : (strlen($basePriceText) <= 6 ? \'28mm\' : \'34mm\')))}\n{var $strikeMarkup = \'<img class=\"vel2-strike-img\" src=\"\' . $strikeSlashDataUri . \'\" style=\"width:\' . $strikeWidth . \'\" alt=\"\">\'}\n\n<div class=\"fikko-vel2 {$vel2Classes}\">\n    <div class=\"vel2-logo-col\">\n        {$logoMarkup|noescape}\n        <div class=\"vel2-logo-divider\"></div>\n        <div class=\"vel2-brand-text\">\n            <div>Mega</div>\n            <div>Super</div>\n            <div>Cena</div>\n        </div>\n    </div>\n\n    <div class=\"vel2-content-col\">\n        <div class=\"vel2-prod-name\">{$labelName}</div>\n\n        <table class=\"vel2-meta-table\" cellpadding=\"0\" cellspacing=\"0\">\n            <tr>\n                <td class=\"vel2-meta-left\">\n                    <div n:if=\"$label && $label->is_more_species\" class=\"vel2-more-species\">Více druhů</div>\n                    <div n:if=\"$country\" class=\"vel2-origin-row\">\n                        <span class=\"vel2-origin-label-cell\">Země původu:</span>\n                        <span class=\"vel2-origin-flag-cell\">{$flagMarkup|noescape}</span>\n                        <span class=\"vel2-origin-name-cell\">{$country->name}</span>\n                    </div>\n                </td>\n                <td class=\"vel2-meta-center\">\n                    <div n:if=\"$note1\">{$note1}</div>\n                </td>\n                <td class=\"vel2-meta-right\"></td>\n            </tr>\n        </table>\n\n        <table class=\"vel2-price-table\" cellpadding=\"0\" cellspacing=\"0\">\n            <tr>\n                <td class=\"vel2-price-left\">\n                    <div n:if=\"$isDiscounted && $basePrice > $finalPrice\" class=\"vel2-lowest-row\">\n                        <span class=\"vel2-lowest-label\">Nejnižší cena<br>za 30 dní</span>\n                        <div class=\"vel2-lowest-val-box\">\n                            <span class=\"vel2-lowest-val\">{$basePriceText}&nbsp;{$currencySymbol}</span>\n                            <span class=\"vel2-strike-wrap\">{$strikeMarkup|noescape}</span>\n                        </div>\n                    </div>\n                    <div n:if=\"$isDiscounted && $saving > 0\" class=\"vel2-save-box\">\n                        {$brushMarkup|noescape}\n                        <table class=\"vel2-save-table\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                            <tr>\n                                <td class=\"vel2-save-copy-cell\">UŠETŘÍTE</td>\n                                <td class=\"vel2-save-val-cell\">{$savingText}&nbsp;{$currencySymbol}</td>\n                            </tr>\n                        </table>\n                    </div>\n                </td>\n\n                <td class=\"vel2-price-right\">\n                    <div class=\"vel2-our-label\">Naše cena</div>\n                    <div class=\"vel2-main-price-box\">\n                        <span class=\"vel2-price-major\">{$finalPriceMajor}</span>\n                        <div class=\"vel2-price-minor-col\">\n                            <div class=\"vel2-price-minor\">{$finalPriceMinor}</div>\n                            <div class=\"vel2-price-currency\">{$currencySymbol} / 1 ks</div>\n                        </div>\n                    </div>\n                </td>\n            </tr>\n        </table>\n    </div>\n\n    <div class=\"vel2-bottom-box\">\n        <table class=\"vel2-bottom-table\" cellpadding=\"0\" cellspacing=\"0\">\n            <tr>\n                <td class=\"vel2-bottom-ean\">EAN: {$eanText}</td>\n                <td class=\"vel2-bottom-note3\">\n                    <span n:if=\"$note3 || $note2\">{$note3 ?: $note2}</span>\n                </td>\n                <td class=\"vel2-bottom-unit\">\n                    <span n:if=\"$unit\">cena za {$unit->unitWeight}{$unit->unitShort} = {$unit->price|number:2,\',\',\' \'} {$currencySymbol}</span>\n                </td>\n            </tr>\n        </table>\n    </div>\n</div>\n', 1, 1),
(3, '2026-09-16 08:50:41', 'Fikko Cena A4', 1, 210.00, 297.00, 'always', '<style>\r\n    @page { size: A4; margin: 0; }\r\n    html, body { margin: 0; padding: 0; font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif; background: #fff; color: #111; -webkit-font-smoothing: antialiased; }\r\n    * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }\r\n\r\n    .page {\r\n        box-sizing: border-box;\r\n        width: 100%;\r\n        height: 269mm;\r\n        padding: 14mm;\r\n        background: #fff;\r\n        color: #111;\r\n        overflow: hidden;\r\n        page-break-inside: avoid;\r\n        page-break-after: avoid;\r\n    }\r\n\r\n    .logo-box {\r\n        width: 210mm;\r\n        margin: 6mm -14mm 6mm -14mm;\r\n        text-align: center;\r\n    }\r\n    .logo-box img {\r\n        width: 36mm;\r\n        height: 25mm;\r\n        display: inline-block;\r\n    }\r\n\r\n    .header-box {\r\n        display: table;\r\n        width: 210mm;\r\n        height: 23mm;\r\n        background: #111;\r\n        color: #fff;\r\n        text-align: center;\r\n        margin: 0 -14mm;\r\n    }\r\n    .header-box .title {\r\n        display: table-cell;\r\n        vertical-align: middle;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 18mm;\r\n        line-height: 1;\r\n        letter-spacing: 0.04em;\r\n    }\r\n\r\n    .content-box {\r\n        margin-top: 3mm;\r\n    }\r\n    .prod-name {\r\n        font-size: 8mm;\r\n        line-height: 1.15;\r\n        font-weight: 400;\r\n        text-align: center;\r\n        padding-bottom: 2mm;\r\n    }\r\n\r\n    .subtitle-box {\r\n        text-align: center;\r\n        padding-bottom: 1.5mm;\r\n    }\r\n    .subtitle-box .sub-text {\r\n        font-family: Nunito, sans-serif;\r\n        font-style: italic;\r\n        font-weight: 400;\r\n        font-size: 6mm;\r\n        line-height: 1.1;\r\n    }\r\n\r\n    .main-row {\r\n        position: relative;\r\n        padding-top: 2mm;\r\n    }\r\n    .left-col {\r\n        position: absolute;\r\n        top: 0;\r\n        left: 0;\r\n        white-space: nowrap;\r\n    }\r\n    .note1-text {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 6mm;\r\n        line-height: 1.1;\r\n        margin-bottom: 4mm;\r\n        white-space: nowrap;\r\n    }\r\n    .origin-box {\r\n        display: table;\r\n        white-space: nowrap;\r\n    }\r\n    .origin-box .flag-cell {\r\n        display: table-cell;\r\n        width: 15mm;\r\n        vertical-align: middle;\r\n    }\r\n    .origin-box .flag-img {\r\n        width: 15mm;\r\n        height: 15mm;\r\n        display: block;\r\n        border: 0.4mm solid #111;\r\n        border-radius: 50%;\r\n    }\r\n    .origin-box .flag-text {\r\n        display: table-cell;\r\n        padding-left: 3.5mm;\r\n        vertical-align: middle;\r\n        white-space: nowrap;\r\n    }\r\n    .origin-box .flag-label {\r\n        font-size: 3.5mm;\r\n        letter-spacing: 0.08em;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        opacity: 0.65;\r\n        white-space: nowrap;\r\n    }\r\n    .origin-box .flag-name {\r\n        font-size: 5.3mm;\r\n        font-weight: 800;\r\n        line-height: 1.1;\r\n        white-space: nowrap;\r\n    }\r\n\r\n    .price-col {\r\n        text-align: center;\r\n        margin-left: 45mm;\r\n    }\r\n    .lowest-box {\r\n        position: relative;\r\n        text-align: right;\r\n        padding-right: 15mm;\r\n        margin-bottom: 1.5mm;\r\n    }\r\n    .lowest-label {\r\n        display: inline-block;\r\n        vertical-align: middle;\r\n        font-size: 3.6mm;\r\n        line-height: 1.2;\r\n        letter-spacing: 0.06em;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        text-align: right;\r\n        margin-right: 3mm;\r\n    }\r\n    .lowest-val-box {\r\n        position: relative;\r\n        display: inline-block;\r\n        vertical-align: middle;\r\n    }\r\n    .lowest-val {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 11mm;\r\n        line-height: 1;\r\n        color: #111;\r\n    }\r\n    .lowest-val span {\r\n        font-size: 6.5mm;\r\n    }\r\n    .a4-strike-wrap { position: absolute; left: 0; top: 0; width: 0; height: 0; overflow: visible; display: inline-block; }\r\n    .lowest-strike-img {\r\n        position: absolute;\r\n        left: -2mm;\r\n        top: 6.0mm;\r\n        height: 7mm;\r\n    }\r\n\r\n    .our-label {\r\n        font-size: 4mm;\r\n        letter-spacing: 0.1em;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        margin-bottom: 2mm;\r\n    }\r\n\r\n    .main-price {\r\n        display: table;\r\n        margin: 0 auto;\r\n        white-space: nowrap;\r\n    }\r\n    .price-major {\r\n        display: table-cell;\r\n        vertical-align: top;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 61mm;\r\n        line-height: 0.82;\r\n        letter-spacing: -0.03em;\r\n    }\r\n    .price-minor-col {\r\n        display: table-cell;\r\n        vertical-align: top;\r\n        padding-left: 2mm;\r\n        text-align: left;\r\n    }\r\n    .price-minor {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 23.5mm;\r\n        line-height: 0.9;\r\n    }\r\n    .price-currency {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 6.5mm;\r\n        line-height: 0.9;\r\n        white-space: nowrap;\r\n        margin-top: 13mm;\r\n    }\r\n\r\n    .save-box {\r\n        position: relative;\r\n        width: 112mm;\r\n        height: 19mm;\r\n        margin: 3.5mm auto 0 auto;\r\n        color: #fff;\r\n    }\r\n    .save-brush {\r\n        position: absolute;\r\n        top: 0;\r\n        left: 0;\r\n        width: 100%;\r\n        height: 100%;\r\n        z-index: 0;\r\n    }\r\n    .save-inner {\r\n        position: relative;\r\n        z-index: 1;\r\n        width: 100%;\r\n        height: 19mm;\r\n        text-align: center;\r\n    }\r\n    .save-table {\r\n        height: 19mm;\r\n        border-collapse: collapse;\r\n        margin: 0 auto;\r\n    }\r\n    .save-pig-cell {\r\n        vertical-align: middle;\r\n        text-align: right;\r\n        padding-right: 3.5mm;\r\n    }\r\n    .save-pig {\r\n        display: block;\r\n        width: 11.5mm;\r\n        height: 11.5mm;\r\n    }\r\n    .save-copy-cell {\r\n        vertical-align: middle;\r\n        text-align: left;\r\n        white-space: nowrap;\r\n        font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif;\r\n        font-size: 6.8mm;\r\n        font-weight: 800;\r\n        letter-spacing: 0.08em;\r\n        text-transform: uppercase;\r\n        color: #fff;\r\n        line-height: 1;\r\n        padding-right: 3.5mm;\r\n    }\r\n    .save-val-cell {\r\n        vertical-align: middle;\r\n        text-align: left;\r\n        white-space: nowrap;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 13.5mm;\r\n        line-height: 1;\r\n        color: #fff;\r\n    }\r\n\r\n    .unit-box {\r\n        margin-top: 2mm;\r\n        font-size: 4.8mm;\r\n        font-weight: 700;\r\n    }\r\n    .unit-val {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 6mm;\r\n        margin-left: 2mm;\r\n    }\r\n\r\n    .note3-box {\r\n        text-align: center;\r\n        margin-top: 6mm;\r\n        clear: both;\r\n    }\r\n    .note3-text {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 6mm;\r\n        line-height: 1.15;\r\n        text-align: center;\r\n        max-width: 150mm;\r\n        margin: 0 auto;\r\n    }\r\n\r\n    .bottom-box {\r\n        display: table;\r\n        width: 100%;\r\n        margin-top: 6mm;\r\n        clear: both;\r\n    }\r\n    .barcode-col {\r\n        display: table-cell;\r\n        vertical-align: bottom;\r\n        width: 50mm;\r\n        text-align: left;\r\n    }\r\n    .barcode-bars {\r\n        display: block;\r\n        height: 8.5mm;\r\n        white-space: nowrap;\r\n    }\r\n    .barcode-ean {\r\n        font-size: 2.9mm;\r\n        letter-spacing: 0.14em;\r\n        font-weight: 600;\r\n        margin-top: 1mm;\r\n    }\r\n\r\n    .validity-box {\r\n        display: table-cell;\r\n        vertical-align: bottom;\r\n        text-align: center;\r\n        padding-bottom: 1mm;\r\n    }\r\n    .validity-text {\r\n        font-size: 3.6mm;\r\n        font-weight: 600;\r\n        letter-spacing: 0.02em;\r\n        white-space: nowrap;\r\n    }\r\n\r\n    .price-digits-3 .price-major { font-size: 50mm; }\r\n    .price-digits-3 .price-minor { font-size: 20mm; }\r\n    .price-digits-3 .price-currency { margin-top: 10mm; font-size: 6mm; }\r\n    \r\n</style>\r\n\r\n{var $pageClasses = \'page\' . ($priceDigits >= 3 ? \' price-digits-3\' : \'\')}\r\n{var $logoMarkup = \'<img src=\"\' . $logoDataUri . \'\" alt=\"Fikko market\">\'}\r\n{var $flagMarkup = $flagIconDataUri ? \'<img class=\"flag-img\" src=\"\' . $flagIconDataUri . \'\" alt=\"\">\' : \'\'}\r\n{var $brushMarkup = \'<img class=\"save-brush\" src=\"\' . $brushDataUri . \'\" alt=\"\">\'}\r\n{var $pigMarkup = \'<img class=\"save-pig\" src=\"\' . $pigIconDataUri . \'\" alt=\"\">\'}\r\n{var $strikeWidth = (strlen($basePriceText) <= 4 ? \'38mm\' : (strlen($basePriceText) <= 5 ? \'44mm\' : (strlen($basePriceText) <= 6 ? \'54mm\' : \'64mm\')))}\r\n{var $strikeMarkup = \'<img class=\"lowest-strike-img\" src=\"\' . $strikeSlashDataUri . \'\" style=\"width:\' . $strikeWidth . \'\" alt=\"\">\'}\r\n\r\n<section class=\"{$pageClasses}\" data-document-role=\"page\" data-label=\"Fikko Cena – tem A4 Akce\" data-screen-label=\"A4 – 1 tem\">\r\n\r\n    <div class=\"logo-box\">\r\n        {$logoMarkup|noescape}\r\n    </div>\r\n\r\n    <header class=\"header-box\">\r\n        <div class=\"title\">FIKKO CENA</div>\r\n    </header>\r\n\r\n    <div class=\"content-box\">\r\n        <div class=\"prod-name\">{$labelName}</div>\r\n\r\n        <div n:if=\"$label && $label->is_more_species\" class=\"subtitle-box\">\r\n            <div class=\"sub-text\">Více druhů</div>\r\n        </div>\r\n\r\n        <div class=\"main-row\">\r\n            <div class=\"left-col\">\r\n                <div n:if=\"$note1\" class=\"note1-text\">{$note1}</div>\r\n                <div n:if=\"$country\" class=\"origin-box\">\r\n                    <div class=\"flag-cell\">{$flagMarkup|noescape}</div>\r\n                    <div class=\"flag-text\">\r\n                        <div class=\"flag-label\">Země původu</div>\r\n                        <div class=\"flag-name\">{$country->name}</div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"price-col\">\r\n                <div class=\"lowest-box\">\r\n                    <div class=\"lowest-label\">Nejnižší cena<br>za 30 dní</div>\r\n                    <div class=\"lowest-val-box\">\r\n                        <span class=\"lowest-val\">{$basePriceText} <span>{$currencySymbol}</span></span><span class=\"a4-strike-wrap\">{$strikeMarkup|noescape}</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"our-label\">Naše cena</div>\r\n\r\n                <div class=\"main-price\">\r\n                    <div class=\"price-major\">{$finalPriceMajor}</div>\r\n                    <div class=\"price-minor-col\">\r\n                        <div class=\"price-minor\">{$finalPriceMinor}</div>\r\n                        <div class=\"price-currency\">{$currencySymbol} / ks</div>\r\n                    </div>\r\n                </div>\r\n\r\n                <div n:if=\"$saving > 0\" class=\"save-box\">\r\n                    {$brushMarkup|noescape}\r\n                    <div class=\"save-inner\">\r\n                        <table class=\"save-table\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\r\n                            <tr>\r\n                                <td class=\"save-pig-cell\">\r\n                                    {$pigMarkup|noescape}\r\n                                </td>\r\n                                <td class=\"save-copy-cell\">\r\n                                    UŠETŘÍTE\r\n                                </td>\r\n                                <td class=\"save-val-cell\">\r\n                                    {$savingText}&nbsp;{$currencySymbol}\r\n                                </td>\r\n                            </tr>\r\n                        </table>\r\n                    </div>\r\n                </div>\r\n\r\n                <div n:if=\"$unit\" class=\"unit-box\">\r\n                    <span>Cena za {$unit->unitWeight} {$unit->unitShort}</span>\r\n                    <span class=\"unit-val\">{$unit->price|number:2,\',\',\' \'} {$currencySymbol}</span>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div n:if=\"$note3 || $note2\" class=\"note3-box\">\r\n            <div class=\"note3-text\">{$note3 ?: $note2}</div>\r\n        </div>\r\n\r\n        <div class=\"bottom-box\">\r\n            <div class=\"barcode-col\">\r\n                <div n:if=\"$bars\" class=\"barcode-bars\">\r\n                    <div n:foreach=\"$bars as $bar\" style=\"float:left;height:8.5mm;background:{$bar[\'color\']|noescape};width:{$bar[\'width\']|noescape}\"></div>\r\n                    <div style=\"clear:both\"></div>\r\n                </div>\r\n                <div n:if=\"$eanText\" class=\"barcode-ean\">EAN {$eanText}</div>\r\n            </div>\r\n\r\n            <div n:if=\"!$hideValidity && $validityText\" class=\"validity-box\">\r\n                <div class=\"validity-text\">Akce platí do <b>{$validityText}</b> nebo do vyprodání zásob</div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n</section>\r\n', 1, 1),
(8, '2026-09-16 23:08:02', 'Fikko Cena A5', 2, 200.00, 138.50, 'always', '<style>\r\n    @page { size: A4; margin: 0; }\r\n    html, body { margin: 0; padding: 0; font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif; background: #fff; color: #111; -webkit-font-smoothing: antialiased; }\r\n    * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }\r\n\r\n    .a5-half {\r\n        box-sizing: border-box;\r\n        width: 210mm;\r\n        height: 148.5mm;\r\n        padding: 0;\r\n        background: #fff;\r\n        color: #111;\r\n        overflow: hidden;\r\n        position: relative;\r\n    }\r\n\r\n    .a5-header {\r\n        display: table;\r\n        width: 210mm;\r\n        height: 18mm;\r\n        background: #111;\r\n        color: #fff;\r\n    }\r\n    .a5-logo-cell {\r\n        display: table-cell;\r\n        width: 22mm;\r\n        height: 18mm;\r\n        background: #fff;\r\n        text-align: center;\r\n        vertical-align: middle;\r\n        padding: 1mm;\r\n    }\r\n    .a5-logo-cell img {\r\n        width: 20mm;\r\n        height: 16mm;\r\n        object-fit: contain;\r\n        display: block;\r\n        margin: 0 auto;\r\n    }\r\n    .a5-title-cell {\r\n        display: table-cell;\r\n        vertical-align: middle;\r\n        text-align: center;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 11.5mm;\r\n        line-height: 1;\r\n        letter-spacing: 0.02em;\r\n        color: #fff;\r\n        padding-right: 22mm;\r\n    }\r\n\r\n    .a5-content {\r\n        width: 194mm;\r\n        margin: 1.5mm auto 0 auto;\r\n    }\r\n\r\n    .a5-prod-name {\r\n        font-size: 5.5mm;\r\n        line-height: 1.15;\r\n        font-weight: 400;\r\n        text-align: center;\r\n        padding-bottom: 0.5mm;\r\n    }\r\n\r\n    .a5-subtitle-row {\r\n        text-align: center;\r\n        padding-bottom: 0.5mm;\r\n    }\r\n    .a5