 border-radius: 50%;\r\n    }\r\n    .a5-origin-text-cell {\r\n        display: table-cell;\r\n        padding-left: 2.5mm;\r\n        vertical-align: middle;\r\n        white-space: nowrap;\r\n    }\r\n    .a5-origin-label {\r\n        font-size: 2.5mm;\r\n        letter-spacing: 0.08em;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        color: #111;\r\n        white-space: nowrap;\r\n    }\r\n    .a5-origin-name {\r\n        font-size: 3.8mm;\r\n        font-weight: 800;\r\n        line-height: 1.1;\r\n        white-space: nowrap;\r\n    }\r\n\r\n    .a5-ingredients-box {\r\n        margin-top: 0.5mm;\r\n    }\r\n    .a5-ingredients-label {\r\n        font-size: 2.5mm;\r\n        letter-spacing: 0.08em;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        opacity: 0.65;\r\n    }\r\n    .a5-ingredients-text {\r\n        font-size: 8.5pt;\r\n        line-height: 1.15;\r\n        font-weight: 400;\r\n        max-height: 15mm;\r\n        overflow: hidden;\r\n    }\r\n\r\n    .a5-right-col {\r\n        vertical-align: top;\r\n        text-align: center;\r\n    }\r\n\r\n    .a5-price-col {\r\n        text-align: center;\r\n    }\r\n\r\n    .a5-lowest-box {\r\n        position: relative;\r\n        text-align: right;\r\n        padding-right: 12mm;\r\n        margin-bottom: 0.8mm;\r\n        white-space: nowrap;\r\n    }\r\n    .a5-lowest-label {\r\n        display: inline-block;\r\n        vertical-align: middle;\r\n        font-size: 2.7mm;\r\n        line-height: 1.2;\r\n        letter-spacing: 0.04em;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        color: #111;\r\n        text-align: right;\r\n        margin-right: 2.5mm;\r\n    }\r\n    .a5-strike-wrap { position: absolute; left: 0; top: 0; width: 0; height: 0; overflow: visible; display: inline-block; }\r\n    .a5-lowest-val-box {\r\n        position: relative;\r\n        display: inline-block;\r\n        vertical-align: middle;\r\n    }\r\n    .a5-lowest-val {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 13mm;\r\n        line-height: 1;\r\n        color: #111;\r\n    }\r\n    .a5-lowest-strike-img {\r\n        position: absolute;\r\n        left: -2mm;\r\n        top: 7.5mm;\r\n        height: 6.5mm;\r\n    }\r\n\r\n    .a5-main-price {\r\n        display: table;\r\n        margin: 0 auto;\r\n        white-space: nowrap;\r\n    }\r\n    .a5-price-major {\r\n        display: table-cell;\r\n        vertical-align: top;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 38mm;\r\n        line-height: 0.82;\r\n        letter-spacing: -0.03em;\r\n    }\r\n    .a5-price-minor-col {\r\n        display: table-cell;\r\n        vertical-align: top;\r\n        padding-left: 1.5mm;\r\n        text-align: left;\r\n    }\r\n    .a5-price-minor {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 17mm;\r\n        line-height: 0.9;\r\n    }\r\n    .a5-price-currency {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 7.5mm;\r\n        line-height: 0.9;\r\n        white-space: nowrap;\r\n        margin-top: 1mm;\r\n    }\r\n\r\n    .a5-save-box {\r\n        position: relative;\r\n        width: 76mm;\r\n        height: 10.5mm;\r\n        margin: 0.5mm auto 0 auto;\r\n        color: #fff;\r\n    }\r\n    .a5-save-brush {\r\n        position: absolute;\r\n        top: 0;\r\n        left: 0;\r\n        width: 100%;\r\n        height: 100%;\r\n        z-index: 0;\r\n    }\r\n    .a5-save-inner {\r\n        position: relative;\r\n        z-index: 1;\r\n        width: 100%;\r\n        height: 10.5mm;\r\n        text-align: center;\r\n    }\r\n    .a5-save-table {\r\n        height: 10.5mm;\r\n        border-collapse: collapse;\r\n        margin: 0 auto;\r\n    }\r\n    .a5-save-pig-cell {\r\n        vertical-align: middle;\r\n        text-align: right;\r\n        padding-right: 2mm;\r\n    }\r\n    .a5-save-pig {\r\n        display: block;\r\n        width: 5.5mm;\r\n        height: 5.5mm;\r\n    }\r\n    .a5-save-copy-cell {\r\n        vertical-align: middle;\r\n        text-align: left;\r\n        white-space: nowrap;\r\n        font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif;\r\n        font-size: 4mm;\r\n        font-weight: 700;\r\n        letter-spacing: 0.1em;\r\n        text-transform: uppercase;\r\n        color: #fff;\r\n        line-height: 1;\r\n        padding-right: 2mm;\r\n    }\r\n    .a5-save-val-cell {\r\n        vertical-align: middle;\r\n        text-align: left;\r\n        white-space: nowrap;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 7.5mm;\r\n        line-height: 1;\r\n        color: #fff;\r\n    }\r\n\r\n    .a5-note3-box {\r\n        text-align: center;\r\n        padding-top: 1mm;\r\n        padding-bottom: 0.5mm;\r\n        clear: both;\r\n    }\r\n    .a5-note3-text {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 4.5mm;\r\n        line-height: 1.1;\r\n        text-align: center;\r\n        white-space: nowrap;\r\n        overflow: hidden;\r\n    }\r\n\r\n    .a5-bottom-table {\r\n        width: 194mm;\r\n        border-collapse: collapse;\r\n        margin-top: 0.5mm;\r\n    }\r\n    .a5-barcode-cell {\r\n        vertical-align: bottom;\r\n        width: 50mm;\r\n        text-align: left;\r\n    }\r\n    .a5-barcode-bars {\r\n        height: 7.5mm;\r\n        margin-bottom: 0.4mm;\r\n        white-space: nowrap;\r\n    }\r\n    .a5-barcode-bars > div {\r\n        float: left;\r\n        height: 100%;\r\n    }\r\n    .a5-barcode-ean {\r\n        font-size: 2.9mm;\r\n        letter-spacing: 0.14em;\r\n        font-weight: 600;\r\n    }\r\n\r\n    .a5-unit-cell {\r\n        vertical-align: bottom;\r\n        text-align: right;\r\n        font-size: 3.4mm;\r\n        font-weight: 700;\r\n        white-space: nowrap;\r\n    }\r\n    .a5-unit-val {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 4.2mm;\r\n        margin-left: 2.5mm;\r\n    }\r\n\r\n    .a5-validity-box {\r\n        text-align: center;\r\n        padding-top: 0.8mm;\r\n        font-size: 3mm;\r\n        font-weight: 600;\r\n        white-space: nowrap;\r\n    }\r\n    .a5-validity-val {\r\n        font-weight: 800;\r\n    }\r\n\r\n    .price-digits-3 .a5-price-major { font-size: 31mm; }\r\n    .price-digits-3 .a5-price-minor { font-size: 14mm; }\r\n    .price-digits-3 .a5-price-currency { margin-top: 1.5mm; font-size: 6.5mm; }\r\n    .price-digits-3 .a5-lowest-box { padding-right: 9mm; }\r\n</style>\r\n\r\n{var $a5Classes = \'a5-half\' . ($priceDigits >= 3 ? \' price-digits-3\' : \'\')}\r\n{var $logoMarkup = \'<img src=\"\' . $logoDataUri . \'\" alt=\"Fikko market\">\'}\r\n{var $flagMarkup = $flagIconDataUri ? \'<img class=\"a5-origin-flag-img\" src=\"\' . $flagIconDataUri . \'\" alt=\"\">\' : \'\'}\r\n{var $brushMarkup = \'<img class=\"a5-save-brush\" src=\"\' . $brushDataUri . \'\" alt=\"\">\'}\r\n{var $ribbonBrushMarkup = \'<img class=\"a5-ribbon-brush\" src=\"\' . $brushDataUri . \'\" alt=\"\">\'}\r\n{var $pigMarkup = \'<img class=\"a5-save-pig\" src=\"\' . $pigIconDataUri . \'\" alt=\"\">\'}\r\n{var $strikeWidth = (strlen($basePriceText) <= 4 ? \'32mm\' : (strlen($basePriceText) <= 5 ? \'38mm\' : (strlen($basePriceText) <= 6 ? \'48mm\' : \'58mm\')))}\r\n{var $strikeMarkup = \'<img class=\"a5-lowest-strike-img\" src=\"\' . $strikeSlashDataUri . \'\" style=\"width:\' . $strikeWidth . \'\" alt=\"\">\'}\r\n\r\n<div class=\"{$a5Classes}\">\r\n    <header class=\"a5-header\">\r\n        <div class=\"a5-logo-cell\">\r\n            {$logoMarkup|noescape}\r\n        </div>\r\n        <div class=\"a5-title-cell\">\r\n            FIKKO CENA\r\n        </div>\r\n    </header>\r\n\r\n    <div class=\"a5-content\">\r\n        <div class=\"a5-prod-name\">{$labelName}</div>\r\n\r\n        <div n:if=\"($label && $label->is_more_species) || $note1\" class=\"a5-subtitle-row\">\r\n            <div n:if=\"$label && $label->is_more_species\" class=\"a5-more-species\">Více druhů</div>\r\n            <div n:if=\"$note1\" class=\"a5-note1\">{$note1}</div>\r\n        </div>\r\n\r\n        <table class=\"a5-main-table\" cellpadding=\"0\" cellspacing=\"0\">\r\n            <tr>\r\n                <td class=\"a5-left-col\">\r\n                    <div n:if=\"$hasSaleRibbon\" class=\"a5-ribbon-badge\">\r\n                        {$ribbonBrushMarkup|noescape}\r\n                        <table class=\"a5-ribbon-table\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\r\n                            <tr>\r\n                                <td class=\"a5-ribbon-text-cell\">-{$salePercent|number:0}%</td>\r\n                            </tr>\r\n                        </table>\r\n                    </div>\r\n\r\n                    <div n:if=\"$country\" class=\"a5-origin-box\">\r\n                        <div class=\"a5-origin-flag-cell\">{$flagMarkup|noescape}</div>\r\n                        <div class=\"a5-origin-text-cell\">\r\n                            <div class=\"a5-origin-label\">Země původu</div>\r\n                            <div class=\"a5-origin-name\">{$country->name}</div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div n:if=\"!$hideIngredients && $product->ingredients\" class=\"a5-ingredients-box\">\r\n                        <div class=\"a5-ingredients-label\">Složení</div>\r\n                        <div class=\"a5-ingredients-text\">{$product->ingredients|truncate:200}</div>\r\n                    </div>\r\n                </td>\r\n\r\n                <td class=\"a5-right-col\">\r\n                    <div class=\"a5-price-col\">\r\n                        <div n:if=\"$isDiscounted && $basePrice > $finalPrice\" class=\"a5-lowest-box\">\r\n                            <div class=\"a5-lowest-label\">NEJNIŽŠÍ CENA<br>ZA 30 DNÍ</div>\r\n                            <div class=\"a5-lowest-val-box\">\r\n                                <span class=\"a5-lowest-val\">{$basePriceText}</span><span class=\"a5-strike-wrap\">{$strikeMarkup|noescape}</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"a5-main-price\">\r\n                            <div class=\"a5-price-major\">{$finalPriceMajor}</div>\r\n                            <div class=\"a5-price-minor-col\">\r\n                                <div class=\"a5-price-minor\">{$finalPriceMinor}</div>\r\n                                <div class=\"a5-price-currency\">{$currencySymbol} / 1 ks</div>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div n:if=\"$saving > 0\" class=\"a5-save-box\">\r\n                            {$brushMarkup|noescape}\r\n                            <div class=\"a5-save-inner\">\r\n                                <table class=\"a5-save-table\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\r\n                                    <tr>\r\n                                        <td class=\"a5-save-pig-cell\">\r\n                                            {$pigMarkup|noescape}\r\n                                        </td>\r\n                                        <td class=\"a5-save-copy-cell\">\r\n                                            UŠETŘÍTE\r\n                                        </td>\r\n                                        <td class=\"a5-save-val-cell\">\r\n                                            {$savingText}&nbsp;{$currencySymbol}\r\n                                        </td>\r\n                                    </tr>\r\n                                </table>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </td>\r\n            </tr>\r\n        </table>\r\n\r\n        <div n:if=\"$note3 || $note2\" class=\"a5-note3-box\">\r\n            <div class=\"a5-note3-text\">{$note3 ?: $note2}</div>\r\n        </div>\r\n\r\n        <table class=\"a5-bottom-table\" cellpadding=\"0\" cellspacing=\"0\">\r\n            <tr>\r\n                <td class=\"a5-barcode-cell\">\r\n                    <div n:if=\"$bars\" class=\"a5-barcode-bars\">\r\n                        <div n:foreach=\"$bars as $bar\" style=\"height:100%;background:{$bar[\'color\']|noescape};width:{$bar[\'width\']|noescape}\"></div>\r\n                    </div>\r\n                    <div class=\"a5-barcode-ean\">EAN {$eanText}</div>\r\n                </td>\r\n                <td class=\"a5-unit-cell\">\r\n                    <div n:if=\"$unit\">\r\n                        <span>Cena za {$unit->unitWeight} {$unit->unitShort}</span>\r\n                        <span class=\"a5-unit-val\">{$unit->price|number:2,\',\',\' \'} {$currencySymbol}</span>\r\n                    </div>\r\n                </td>\r\n            </tr>\r\n        </table>\r\n\r\n        <div n:if=\"!$hideValidity && $validityText\" class=\"a5-validity-box\">\r\n            Akce platí do <span class=\"a5-validity-val\">{$validityText}</span> nebo do vyprodání zásob\r\n        </div>\r\n    </div>\r\n</div>\r\n', 1, 1),
(9, '2026-09-18 14:11:31', 'Fikko Cena Vel.1', 3, 164.00, 41.00, 'always', '<style>\n    @page { margin: 0; }\n    html, body { margin: 0; padding: 0; font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif; background: #fff; color: #111; -webkit-font-smoothing: antialiased; }\n    * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n\n    .fikko-vel1 {\n        box-sizing: border-box;\n        position: relative;\n        width: 164mm;\n        height: 41mm;\n        border: 0.4mm dashed #111;\n        background: #fff;\n        color: #111;\n        overflow: hidden;\n        font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif;\n    }\n\n    /* Left logo / brand column (24mm x 41mm) */\n    .vel1-logo-col {\n        position: absolute;\n        top: 0;\n        left: 0;\n        width: 24mm;\n        height: 41mm;\n        border-right: 0.4mm dashed #111;\n        text-align: center;\n        padding: 1.2mm 1mm;\n    }\n    .vel1-logo-img {\n        width: 14mm;\n        height: 11mm;\n        object-fit: contain;\n        display: block;\n        margin: 0 auto;\n        filter: grayscale(1) contrast(1.15);\n    }\n    .vel1-logo-divider {\n        width: 21mm;\n        margin: 1.2mm auto 1.2mm auto;\n        border-top: 0.3mm dashed #111;\n    }\n    .vel1-brand-text {\n        text-align: center;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 5.8mm;\n        line-height: 1.05;\n        color: #111;\n    }\n\n    /* Right main content column (140mm x 41mm) */\n    .vel1-content-col {\n        position: absolute;\n        top: 0;\n        left: 27.5mm;\n        width: 134mm;\n        height: 41mm;\n        padding: 0.8mm 1mm 0.6mm 1mm;\n    }\n\n    /* 1. Product Name */\n    .vel1-prod-name {\n        text-align: center;\n        font-size: 3.3mm;\n        font-weight: 400;\n        line-height: 1.05;\n        overflow: hidden;\n        white-space: nowrap;\n        height: 3.5mm;\n    }\n\n    /* 2. Meta row (Origin, Note1, More species) */\n    .vel1-meta-table {\n        width: 100%;\n        border-collapse: collapse;\n        margin-top: 0;\n    }\n    .vel1-meta-left {\n        width: 50mm;\n        vertical-align: middle;\n        text-align: left;\n    }\n    .vel1-meta-center {\n        vertical-align: middle;\n        text-align: center;\n        font-family: Nunito, sans-serif;\n        font-style: italic;\n        font-size: 2.3mm;\n        font-weight: 400;\n        line-height: 1;\n        white-space: nowrap;\n    }\n    .vel1-meta-right {\n        width: 30mm;\n        vertical-align: middle;\n        text-align: right;\n        font-family: Nunito, sans-serif;\n        font-style: italic;\n        font-size: 2.3mm;\n        font-weight: 400;\n        line-height: 1;\n        white-space: nowrap;\n    }\n\n    /* Origin box inside meta-left */\n    .vel1-origin-box {\n        display: table;\n        white-space: nowrap;\n    }\n    .vel1-origin-flag-cell {\n        display: table-cell;\n        width: 6mm;\n        vertical-align: middle;\n    }\n    .vel1-origin-flag-img {\n        width: 5mm;\n        height: 5mm;\n        display: block;\n        border: 0.25mm solid #111;\n        border-radius: 50%;\n    }\n    .vel1-origin-text-cell {\n        display: table-cell;\n        vertical-align: middle;\n        padding-left: 1.3mm;\n        white-space: nowrap;\n    }\n    .vel1-origin-label {\n        font-size: 1.8mm;\n        letter-spacing: 0.08em;\n        text-transform: uppercase;\n        font-weight: 700;\n        color: #111;\n        display: block;\n        line-height: 1;\n    }\n    .vel1-origin-name {\n        font-size: 2.7mm;\n        font-weight: 800;\n        line-height: 1.05;\n        display: block;\n        white-space: nowrap;\n    }\n\n    /* 3. Main Price Comparison Section */\n    .vel1-price-table {\n        width: 100%;\n        border-collapse: collapse;\n        margin-top: 0;\n    }\n    .vel1-price-left {\n        width: 58mm;\n        vertical-align: middle;\n        text-align: right;\n        padding-right: 2.5mm;\n    }\n    .vel1-price-right {\n        vertical-align: middle;\n        text-align: left;\n        padding-left: 2.5mm;\n    }\n\n    /* Běžná cena */\n    .vel1-base-row {\n        white-space: nowrap;\n        text-align: right;\n    }\n    .vel1-base-label {\n        display: inline-block;\n        vertical-align: middle;\n        font-size: 2.1mm;\n        line-height: 1.15;\n        letter-spacing: 0.06em;\n        text-transform: uppercase;\n        font-weight: 700;\n        text-align: right;\n        margin-right: 1.5mm;\n    }\n    .vel1-base-val {\n        display: inline-block;\n        vertical-align: middle;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 6mm;\n        line-height: 1;\n    }\n    .vel1-base-currency {\n        font-size: 3.8mm;\n    }\n\n    /* Ušetříte brush badge */\n    .vel1-save-box {\n        position: relative;\n        width: 50mm;\n        height: 4.4mm;\n        margin-top: 0.2mm;\n        margin-left: auto;\n        transform: rotate(-1.2deg);\n        color: #fff;\n    }\n    .vel1-save-brush {\n        position: absolute;\n        top: 0;\n        left: 0;\n        width: 50mm;\n        height: 4.4mm;\n        z-index: 0;\n    }\n    .vel1-save-table {\n        position: relative;\n        z-index: 1;\n        width: 50mm;\n        height: 4.4mm;\n        border-collapse: collapse;\n        margin: 0 auto;\n    }\n    .vel1-save-copy-cell {\n        vertical-align: middle;\n        text-align: right;\n        font-size: 2mm;\n        letter-spacing: 0.08em;\n        text-transform: uppercase;\n        font-weight: 700;\n        white-space: nowrap;\n        padding-left: 1.5mm;\n    }\n    .vel1-save-val-cell {\n        vertical-align: middle;\n        text-align: center;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 4mm;\n        line-height: 1;\n        white-space: nowrap;\n        padding: 0 0.8mm;\n    }\n    .vel1-save-suffix-cell {\n        vertical-align: middle;\n        text-align: left;\n        font-size: 1.8mm;\n        font-weight: 600;\n        white-space: nowrap;\n        padding-right: 1.5mm;\n    }\n\n    /* Naše cena */\n    .vel1-our-row {\n        white-space: nowrap;\n    }\n    .vel1-our-label {\n        display: inline-block;\n        vertical-align: middle;\n        font-size: 2.1mm;\n        line-height: 1.15;\n        letter-spacing: 0.06em;\n        text-transform: uppercase;\n        font-weight: 700;\n        text-align: right;\n        margin-right: 2mm;\n    }\n    .vel1-main-price-box {\n        display: inline-block;\n        vertical-align: middle;\n        white-space: nowrap;\n    }\n    .vel1-price-major {\n        display: inline-block;\n        vertical-align: top;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 18.5mm;\n        line-height: 0.82;\n    }\n    .vel1-price-minor-col {\n        display: inline-block;\n        vertical-align: top;\n        text-align: left;\n        padding-top: 0.3mm;\n        margin-left: 0.8mm;\n    }\n    .vel1-price-minor {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 8.5mm;\n        line-height: 0.88;\n    }\n    .vel1-price-currency {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 3.4mm;\n        line-height: 0.9;\n        white-space: nowrap;\n        margin-top: 0.3mm;\n    }\n\n    /* 4. Unit price row */\n    .vel1-unit-price {\n        text-align: right;\n        font-family: Nunito, sans-serif;\n        font-style: italic;\n        font-size: 2.1mm;\n        white-space: nowrap;\n        padding-right: 1mm;\n        line-height: 1;\n        margin-top: -0.4mm;\n        margin-bottom: 0.1mm;\n    }\n\n    /* 5. Bottom row (Barcode, Note 3) */\n    .vel1-bottom-box {\n        position: absolute;\n        left: 28mm;\n        right: 2.5mm;\n        bottom: 1.8mm;\n        width: 133.5mm;\n    }\n    .vel1-bottom-table {\n        width: 100%;\n        border-collapse: collapse;\n    }\n    .vel1-barcode-cell {\n        width: 44mm;\n        vertical-align: bottom;\n        text-align: left;\n    }\n    .vel1-barcode-bars {\n        height: 3.5mm;\n        white-space: nowrap;\n        margin-bottom: 0.2mm;\n    }\n    .vel1-barcode-bars > div {\n        float: left;\n        height: 100%;\n    }\n    .vel1-barcode-ean {\n        font-size: 1.8mm;\n        font-weight: 600;\n        white-space: nowrap;\n        letter-spacing: 0.04em;\n        line-height: 1;\n        clear: both;\n    }\n    .vel1-note3-cell {\n        vertical-align: bottom;\n        text-align: center;\n        font-family: Nunito, sans-serif;\n        font-style: italic;\n        font-size: 2.1mm;\n        line-height: 1.15;\n        max-height: 4.2mm;\n        overflow: hidden;\n    }\n    .vel1-bottom-spacer {\n        width: 25mm;\n    }\n\n    /* 3-digit price scaling (e.g. 139,90) */\n    .price-digits-3 .vel1-price-major { font-size: 15.5mm; }\n    .price-digits-3 .vel1-price-minor { font-size: 7.2mm; }\n    .price-digits-3 .vel1-price-currency { font-size: 3mm; margin-top: 0.2mm; }\n    .price-digits-3 .vel1-base-val { font-size: 5.2mm; }\n    .price-digits-3 .vel1-price-left { width: 50mm; }\n</style>\n\n{var $vel1Classes = ($priceDigits >= 3 ? \'price-digits-3\' : \'\')}\n{var $logoMarkup = \'<img class=\"vel1-logo-img\" src=\"\' . $logoDataUri . \'\" alt=\"Fikko market\">\'}\n{var $flagMarkup = $flagIconDataUri ? \'<img class=\"vel1-origin-flag-img\" src=\"\' . $flagIconDataUri . \'\" alt=\"\">\' : \'\'}\n{var $brushMarkup = \'<img class=\"vel1-save-brush\" src=\"\' . $brushDataUri . \'\" alt=\"\">\'}\n\n<div class=\"fikko-vel1 {$vel1Classes}\">\n    <div class=\"vel1-logo-col\">\n        {$logoMarkup|noescape}\n        <div class=\"vel1-logo-divider\"></div>\n        <div class=\"vel1-brand-text\">\n            <div>Fikko</div>\n            <div>Cena</div>\n        </div>\n    </div>\n\n    <div class=\"vel1-content-col\">\n        <div class=\"vel1-prod-name\">{$labelName}</div>\n\n        <table class=\"vel1-meta-table\" cellpadding=\"0\" cellspacing=\"0\">\n            <tr>\n                <td class=\"vel1-meta-left\">\n                    <div n:if=\"$country\" class=\"vel1-origin-box\">\n                        <div class=\"vel1-origin-flag-cell\">{$flagMarkup|noescape}</div>\n                        <div class=\"vel1-origin-text-cell\">\n                            <span class=\"vel1-origin-label\">Země původu</span>\n                            <span class=\"vel1-origin-name\">{$country->name}</span>\n                        </div>\n                    </div>\n                </td>\n                <td class=\"vel1-meta-center\">\n                    <div n:if=\"$note1\">{$note1}</div>\n                </td>\n                <td class=\"vel1-meta-right\">\n                    <div n:if=\"$label && $label->is_more_species\">Více druhů</div>\n                </td>\n            </tr>\n        </table>\n\n        <table class=\"vel1-price-table\" cellpadding=\"0\" cellspacing=\"0\">\n            <tr>\n                <td class=\"vel1-price-left\">\n                    <div n:if=\"$isDiscounted && $basePrice > $finalPrice\" class=\"vel1-base-row\">\n                        <span class=\"vel1-base-label\">Běžná<br>cena</span>\n                        <span class=\"vel1-base-val\">{$basePriceText} <span class=\"vel1-base-currency\">{$currencySymbol}</span></span>\n                    </div>\n                    <div n:if=\"$isDiscounted && $saving > 0\" class=\"vel1-save-box\">\n                        {$brushMarkup|noescape}\n                        <table class=\"vel1-save-table\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                            <tr>\n                                <td class=\"vel1-save-copy-cell\">UŠETŘÍTE</td>\n                                <td class=\"vel1-save-val-cell\">{$savingText}&nbsp;{$currencySymbol}</td>\n                                <td class=\"vel1-save-suffix-cell\">oproti běžné ceně</td>\n                            </tr>\n                        </table>\n                    </div>\n                </td>\n\n                <td class=\"vel1-price-right\">\n                    <div class=\"vel1-our-row\">\n                        <span class=\"vel1-our-label\">Naše<br>cena</span>\n                        <div class=\"vel1-main-price-box\">\n                            <span class=\"vel1-price-major\">{$finalPriceMajor}</span>\n                            <div class=\"vel1-price-minor-col\">\n                                <div class=\"vel1-price-minor\">{$finalPriceMinor}</div>\n                                <div class=\"vel1-price-currency\">{$currencySymbol} / 1 ks</div>\n                            </div>\n                        </div>\n                    </div>\n                </td>\n            </tr>\n        </table>\n\n        <div n:if=\"$unit\" class=\"vel1-unit-price\">\n            cena za {$unit->unitWeight}{$unit->unitShort} = {$unit->price|number:2,\',\',\' \'} {$currencySymbol}\n        </div>\n    </div>\n\n    <div class=\"vel1-bottom-box\">\n        <table class=\"vel1-bottom-table\" cellpadding=\"0\" cellspacing=\"0\">\n            <tr>\n                <td class=\"vel1-barcode-cell\">\n                    <div n:if=\"$bars\" class=\"vel1-barcode-bars\">\n                        <div n:foreach=\"$bars as $bar\" style=\"height:100%;background:{$bar[\'color\']|noescape};width:{$bar[\'width\']|noescape}\"></div>\n                    </div>\n                    <div class=\"vel1-barcode-ean\">EAN: {$eanText}</div>\n                </td>\n                <td class=\"vel1-note3-cell\">\n                    <div n:if=\"$note3 || $note2\">{$note3 ?: $note2}</div>\n                </td>\n                <td class=\"vel1-bottom-spacer\"></td>\n            </tr>\n        </table>\n    </div>\n</div>\n', 1, 1),
(10, '2026-09-18 14:12:00', 'Fikko Cena Vel.3', 5, 182.00, 56.00, 'always', '{* Computed before <style> (not after, where every other per-instance var in this\n   file lives) specifically so $saveBadgeWidthMm and $ribbonBadgeBrushFlatDataUri can be\n   interpolated directly into the .fikko-vel3 .save{} rule below, as ONE stylesheet\n   rule with both properties together. Two separate <style> blocks for the same\n   selector (main block + a second one added just for background-image) were tried\n   first and silently didn\'t apply the second block\'s property at all in Dompdf,\n   even though the generated HTML was well-formed — so both properties must live in\n   the SAME rule, which is why this whole block moved above <style>. *}\n{* 3-digit final prices shift .price-major further left (.price-digits-3, less\n   horizontal budget available on this narrow 182mm label) — the suffix cannot fit\n   there even for a short saving value, so it\'s dropped whenever priceDigits>=3,\n   not just when the saving value itself is long. *}\n{var $saveSuffixFits = mb_strlen($savingText) <= 5 && $priceDigits < 3}\n{* Explicit badge width (mm), formula fitted to real Dompdf measurements of this exact\n   markup/font/padding (not one hardcoded value): base 31.33mm (Ušetříte + padding/gaps\n   with an empty value) + 3mm per character of \"$savingText Kč\" + 23.8mm if the\n   suffix is shown. Verified against measured widths for \"5,00\"/\"10,00\"/\"45,00 Kč\"\n   (with suffix) and \"125,50 Kč\" (without) within ±0.1mm. *}\n{var $saveBadgeWidthMm = 31.33 + mb_strlen($savingText) * 3 + ($saveSuffixFits ? 23.8 : 0)}\n<style>\n    @page { margin: 0; }\n    html, body { margin: 0; padding: 0; background: #fff; color: #111; font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif; }\n    .fikko-vel3 { box-sizing: border-box; position: relative; width: 182mm; height: 56mm; overflow: hidden; }\n    .fikko-vel3 .header { position: absolute; top: 0; left: 0; width: 182mm; height: 11mm; background: #111; }\n    .fikko-vel3 .heading-text { position: absolute; top: 0; left: 16mm; width: 150mm; height: 11mm; display: table; text-align: center; }\n    .fikko-vel3 .heading-text span { display: table-cell; vertical-align: middle; color: #fff; font-family: Nunito, sans-serif; font-weight: 900; font-style: italic; font-size: 7mm; line-height: 1; letter-spacing: .02em; }\n    .fikko-vel3 .logo-box { position: absolute; top: 0; width: 13.6mm; height: 8.6mm; background: #fff; border: .4mm solid #111; padding: .8mm; }\n    .fikko-vel3 .logo-box.left { left: 0; }\n    .fikko-vel3 .logo-box.right { right: 0; }\n    .fikko-vel3 .logo { display: block; width: 100%; height: 100%; object-fit: contain; filter: grayscale(1) contrast(1.15); }\n    .fikko-vel3 .name { position: absolute; top: 11mm; left: 0; width: 182mm; text-align: center; font-size: 4.6mm; font-weight: 800; line-height: 1.15; }\n    .fikko-vel3 .more-species { position: absolute; top: 18.08mm; left: 0; width: 182mm; text-align: center; font-family: Nunito, sans-serif; font-weight: 900; font-style: italic; font-size: 3.6mm; line-height: 1.1; }\n    .fikko-vel3 .note1 { position: absolute; top: 22.34mm; left: 0; width: 182mm; text-align: center; font-family: Nunito, sans-serif; font-weight: 900; font-style: italic; font-size: 3.6mm; line-height: 1.1; white-space: nowrap; }\n    .fikko-vel3 .origin { position: absolute; top: 18.48mm; left: 2.5mm; display: table; white-space: nowrap; }\n    .fikko-vel3 .origin-label { display: table-cell; vertical-align: middle; padding-right: 1.5mm; font-family: Nunito, sans-serif; font-weight: 900; font-style: italic; font-size: 2.8mm; }\n    .fikko-vel3 .origin-flag { display: table-cell; vertical-align: middle; width: 8.53mm; }\n    .fikko-vel3 .origin-flag img { display: block; width: 8.53mm; height: 8.53mm; border-radius: 50%; border: .2mm solid #111; box-sizing: border-box; }\n    .fikko-vel3 .origin-name { display: table-cell; vertical-align: middle; padding-left: 1.5mm; font-family: Nunito, sans-serif; font-weight: 900; font-style: italic; font-size: 2.8mm; white-space: nowrap; }\n    .fikko-vel3 .note2 { position: absolute; top: 18.48mm; right: 2.5mm; font-family: Nunito, sans-serif; font-weight: 900; font-style: italic; font-size: 2.8mm; white-space: nowrap; }\n    .fikko-vel3 .base-label { position: absolute; top: 30mm; left: 37.36mm; font-size: 2.8mm; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; white-space: nowrap; }\n    .fikko-vel3 .base-value { position: absolute; top: 27.82mm; left: 60.52mm; font-family: Nunito, sans-serif; font-weight: 900; font-style: italic; font-size: 6mm; line-height: 1; white-space: nowrap; }\n    /* The badge must fit \"Ušetříte X Kč oproti běžné ceně\" for any length of X\n       (5 Kč vs 125,50 Kč) without clipping or overlapping \"Naše cena\" to its right.\n       width and background-image are both interpolated straight into THIS ONE\n       stylesheet rule (which is why $saveBadgeWidthMm/$saveSuffixFits are computed\n       near the top of this file, before <style>, instead of down by the markup like\n       every other per-instance value here) — two things were tried and rejected\n       first: (1) an <img> element (position:absolute;inset:0;width:100%), the\n       pattern every other \"Ušetříte\" badge in this project uses (A4/A5/Vel.2B) —\n       rendered correctly in Chrome\'s PDF.js but bled tens of mm past the box\'s\n       right edge, covering \"Naše cena\", in Chrome\'s actual built-in PDF viewer\n       (PDFium, what a real user sees) — confirmed the bleed persisted with\n       z-index removed, the brush recolored, overflow:hidden added, and rotate()\n       removed, and stopped only once the <img> was gone entirely; (2) the same\n       background-image set inline via style=\"\" alongside width — the width applied\n       but the image silently never painted, in a SEPARATE <style> block targeting\n       the same selector, in Dompdf. Keeping both properties in one rule, in the\n       main stylesheet, is the one arrangement that measures the right width AND\n       actually attempts to paint the brush.\n       Getting the box sized/positioned right still wasn\'t enough: background-image\n       painted as a flat navy rectangle, no brush texture, even though the generated\n       CSS was valid and the GD buffer Dompdf composited internally (dumped to disk\n       mid-render) had the correct jagged brush edges. Root cause, confirmed by\n       instrumenting vendor/dompdf: Cpdf::addImagePngAlpha — the pure-GD path used to\n       embed a background-image with an alpha channel — has a real bug with 8-bit\n       RGBA PNGs (its own source has a \"FIXME: doesn\'t work well with 8bit PNGs\"\n       comment on the affected branch); it silently produces an invisible image while\n       reporting no error, leaving only the background-color underneath visible. A\n       plain <img> tag with the exact same alpha PNG renders fine (it goes through\n       the same function but is never invisible in practice), so this is specific to\n       the background-image call path. Fix: use $ribbonBadgeBrushFlatDataUri (NOT the\n       plain $ribbonBadgeBrushDataUri A4/A5/Vel.2B use via <img> — kept separate on\n       purpose, see PrintTemplatesService), which points at\n       brush-20-ribbon-badge-flat.png, the same navy artwork pre-flattened onto an\n       opaque white background (no alpha channel — PNG color type 2, not 6), which\n       sidesteps the buggy code path entirely. This only works because this badge\n       always sits on the label\'s plain white background; background-color stays as\n       a cheap fallback in case the image ever fails to load for an unrelated reason.\n       IMPORTANT — always verify anything touching this element\'s image against\n       pdf_screenshot_headed.js (opens the real PDF in Chrome\'s own viewer), not\n       pdf_to_png.js (PDF.js canvas) alone; the two have disagreed more than once. */\n    .fikko-vel3 .save { position: absolute; top: 36.5mm; left: 32.6mm; width: {$saveBadgeWidthMm|noescape}mm; height: 9.8mm; color: #fff; white-space: nowrap; background-color: #14142e; background-image: url(\'{$ribbonBadgeBrushFlatDataUri|noescape}\'); background-repeat: no-repeat; background-size: 100% 100%; }\n    .fikko-vel3 .save-content { position: absolute; top: 0; left: 4mm; right: 4mm; height: 100%; display: table; }\n    .fikko-vel3 .save-copy, .fikko-vel3 .save-value, .fikko-vel3 .save-suffix { display: table-cell; vertical-align: middle; }\n    .fikko-vel3 .save-copy { font-size: 2.6mm; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }\n    .fikko-vel3 .save-value { padding-left: 1.5mm; font-family: Nunito, sans-serif; font-weight: 900; font-style: italic; font-size: 5mm; line-height: 1; }\n    .fikko-vel3 .save-suffix { padding-left: 1.5mm; font-size: 2.2mm; font-weight: 600; }\n    /* Design positions (measured directly off velikost 3.dc.html, matched exactly\n       before this shift): our-price-label left:108.2mm, price-major left:102.11mm,\n       price-minor/currency left:126.91mm. Now that the Ušetříte badge next to this\n       has an explicit, measured width (see .save above) instead of growing\n       unboundedly, only a small +3mm safety margin is needed — not the +10mm this\n       carried while that was still unresolved — to clear the badge\'s worst case\n       (5-char saving with the suffix shown, e.g. \"45,00 Kč oproti běžné ceně\", ends\n       at 32.6mm + ~70.1mm ≈ 102.7mm) while staying as close as possible to the\n       source design. */\n    .fikko-vel3 .our-price-label { position: absolute; top: 25.71mm; left: 111.2mm; font-size: 2.8mm; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; white-space: nowrap; }\n    .fikko-vel3 .price-major { position: absolute; top: 26mm; left: 105.11mm; font-family: Nunito, sans-serif; font-weight: 900; font-style: italic; font-size: 19mm; line-height: .85; white-space: nowrap; }\n    .fikko-vel3 .price-minor { position: absolute; top: 27.8mm; left: 129.91mm; font-family: Nunito, sans-serif; font-weight: 900; font-style: italic; font-size: 9mm; line-height: 1; white-space: nowrap; }\n    .fikko-vel3 .price-currency { position: absolute; top: 37.12mm; left: 129.91mm; font-family: Nunito, sans-serif; font-weight: 900; font-style: italic; font-size: 5.5mm; line-height: 1; white-space: nowrap; }\n    .fikko-vel3 .ean-text { position: absolute; left: 2.5mm; bottom: 2.5mm; font-size: 3mm; font-weight: 600; white-space: nowrap; }\n    .fikko-vel3 .notes-bottom { position: absolute; left: 80.67mm; bottom: 2.5mm; font-family: Nunito, sans-serif; font-weight: 900; font-style: italic; font-size: 2.8mm; white-space: nowrap; }\n    .fikko-vel3 .unit { position: absolute; right: 2.5mm; bottom: 2.5mm; font-family: Nunito, sans-serif; font-weight: 900; font-style: italic; font-size: 2.8mm; white-space: nowrap; }\n    .fikko-vel3.long-name .more-species { top: 23.5mm; }\n    .fikko-vel3.long-name .note1 { top: 27.8mm; }\n    .fikko-vel3.long-name .origin { top: 23.9mm; }\n    .fikko-vel3.long-name .note2 { top: 23.9mm; }\n    .fikko-vel3.price-digits-3 .our-price-label { left: 96mm; }\n    .fikko-vel3.price-digits-3 .price-major { left: 90mm; font-size: 15mm; }\n    .fikko-vel3.price-digits-3 .price-minor { left: 121mm; top: 29.1mm; font-size: 7mm; }\n    .fikko-vel3.price-digits-3 .price-currency { left: 121mm; top: 36.1mm; font-size: 4.5mm; }\n</style>\n\n{var $vel3Classes = \'fikko-vel3\' . ($priceDigits >= 3 ? \' price-digits-3\' : \'\') . ($labelNameLength > 62 ? \' long-name\' : \'\')}\n{var $logoMarkup = \'<img class=\"logo\" src=\"\' . $logoDataUri . \'\" alt=\"Fikko market\">\'}\n{var $flagMarkup = $flagIconDataUri ? \'<img src=\"\' . $flagIconDataUri . \'\" alt=\"\">\' : \'\'}\n<section class=\"{$vel3Classes}\">\n    <div class=\"header\"></div>\n    <div class=\"heading-text\"><span>FIKKO CENA</span></div>\n    <div class=\"logo-box left\">{$logoMarkup|noescape}</div>\n    <div class=\"logo-box right\">{$logoMarkup|noescape}</div>\n\n    <div class=\"name\">{$labelName}</div>\n    <div n:if=\"$label && $label->is_more_species\" class=\"more-species\">Více druhů</div>\n    <div n:if=\"$note1\" class=\"note1\">{$note1}</div>\n\n    <div n:if=\"$country\" class=\"origin\">\n        <div class=\"origin-label\">Země původu:</div>\n        <div class=\"origin-flag\">{$flagMarkup|noescape}</div>\n        <div class=\"origin-name\">{$country->name}</div>\n    </div>\n    <div n:if=\"$note2\" class=\"note2\">{$note2}</div>\n\n    <div class=\"base-label\">Běžná cena</div>\n    <div class=\"base-value\">{$basePriceText} {$currencySymbol}</div>\n    <div n:if=\"$saving > 0\" class=\"save\"><div class=\"save-content\"><span class=\"save-copy\">Ušetříte</span><span class=\"save-value\">{$savingText} {$currencySymbol}</span><span n:if=\"$saveSuffixFits\" class=\"save-suffix\">oproti běžné ceně</span></div></div>\n\n    <div class=\"our-price-label\">Naše cena</div>\n    <div class=\"price-major\">{$finalPriceMajor}</div>\n    <div class=\"price-minor\">{$finalPriceMinor}</div>\n    <div class=\"price-currency\">{$currencySymbol} / 1 ks</div>\n\n    <div class=\"ean-text\">EAN {$eanText}</div>\n    <div n:if=\"$note3\" class=\"notes-bottom\">{$note3}</div>\n    <div n:if=\"$unit\" class=\"unit\">cena za {$unit->unitWeight}{$unit->unitShort} = {$unit->price|number:2,\',\',\'\'} {$currencySymbol}</div>\n</section>\n', 0, 0),
(11, '2026-10-05 08:08:06', 'Fikko Cena Ovoce', 5, 50.00, 35.00, 'always', '<style>\n    @page { size: 50mm 35mm; margin: 0; }\n    html, body {\n        margin: 0;\n        padding: 0;\n        background: #ffffff;\n        color: #111111;\n        font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif;\n    }\n    * { box-sizing: border-box; }\n\n    .fikko-fruit {\n        position: relative;\n        width: 50mm;\n        height: 35mm;\n        padding: 1.6mm 2mm;\n        background: #ffffff;\n        color: #111111;\n        overflow: hidden;\n        page-break-after: always;\n    }\n\n    .fikko-fruit .product-title {\n        position: absolute;\n        top: 1.6mm;\n        left: 2mm;\n        width: 46mm;\n        font-size: 2.8mm;\n        font-weight: 800;\n        line-height: 1.1;\n        word-wrap: break-word;\n        word-break: break-word;\n    }\n\n    .fikko-fruit .title-divider {\n        position: absolute;\n        top: 5.6mm;\n        left: 2mm;\n        width: 46mm;\n        border-top: 0.25mm solid #111111;\n    }\n\n    /* Middle section: Weight / Price per kg (Left) vs Price (Right) */\n    .fikko-fruit .weight-col {\n        position: absolute;\n        top: 6.6mm;\n        left: 2mm;\n        width: 25mm;\n    }\n\n    .fikko-fruit .meta-label {\n        font-size: 1.5mm;\n        letter-spacing: 0.04em;\n        text-transform: uppercase;\n        font-weight: 700;\n        line-height: 1.1;\n    }\n\n    .fikko-fruit .meta-val {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.9mm;\n        line-height: 1.05;\n        margin-top: 0.2mm;\n    }\n\n    .fikko-fruit .meta-item-spacing {\n        margin-top: 0.6mm;\n    }\n\n    .fikko-fruit .price-col {\n        position: absolute;\n        top: 6.6mm;\n        right: 2mm;\n        width: 21mm;\n        text-align: right;\n    }\n\n    .fikko-fruit .price-header-label {\n        font-size: 1.6mm;\n        letter-spacing: 0.06em;\n        text-transform: uppercase;\n        font-weight: 700;\n        text-align: right;\n        margin-bottom: 0.6mm;\n        line-height: 1;\n    }\n\n    .fikko-fruit .price-wrap {\n        display: inline-block;\n        white-space: nowrap;\n        text-align: right;\n    }\n\n    .fikko-fruit .price-major {\n        display: inline-block;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 8mm;\n        line-height: 0.85;\n        letter-spacing: -0.02em;\n        vertical-align: top;\n    }\n\n    .fikko-fruit .price-side {\n        display: inline-block;\n        vertical-align: top;\n        text-align: left;\n        margin-left: 0.4mm;\n    }\n\n    .fikko-fruit .price-minor {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 3.6mm;\n        line-height: 0.9;\n    }\n\n    .fikko-fruit .price-currency {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.4mm;\n        line-height: 0.9;\n        margin-top: 0.3mm;\n    }\n\n    /* Bottom section: Details (Left) vs Barcode (Right) */\n    .fikko-fruit .details-col {\n        position: absolute;\n        bottom: 3.8mm;\n        left: 2mm;\n        width: 25.5mm;\n        font-size: 1.6mm;\n        line-height: 1.2;\n    }\n\n    .fikko-fruit .details-col div {\n        white-space: nowrap;\n        overflow: hidden;\n        text-overflow: ellipsis;\n    }\n\n    .fikko-fruit .barcode-col {\n        position: absolute;\n        bottom: 3.8mm;\n        right: 2mm;\n        width: 20mm;\n        text-align: center;\n    }\n\n    .fikko-fruit .barcode-bars {\n        width: 19mm;\n        height: 4.5mm;\n        margin: 0 auto;\n        overflow: hidden;\n    }\n\n    .fikko-fruit .barcode-ean {\n        font-size: 1.4mm;\n        letter-spacing: 0.06em;\n        text-align: center;\n        margin-top: 0.2mm;\n        line-height: 1.1;\n    }\n\n    .fikko-fruit .footer-text {\n        position: absolute;\n        bottom: 1.4mm;\n        left: 2mm;\n        width: 46mm;\n        font-size: 1.4mm;\n        line-height: 1.1;\n        opacity: 0.85;\n        white-space: nowrap;\n        overflow: hidden;\n        text-overflow: ellipsis;\n    }\n</style>\n\n{var $packedDate = $label?->datetime_printed ? $label->datetime_printed->format(\'d.m.Y\') : date(\'d.m.Y\')}\n{var $expiryDate = $validityText ?: date(\'d.m.Y\', strtotime(\'+2 days\'))}\n{var $countryName = $country ? $country->name : ($product->getCountry()?->name ?: \'Thajsko\')}\n{var $weightVal = $note1 ?: ($unit ? $unit->unitWeight . \' \' . $unit->unitShort : \'0,486 kg\')}\n{var $unitPriceVal = $unitText ?: ($unit ? ($unit->price|number:2,\',\',\'\') . \' \' . $currencySymbol : \'129,90 Kč\')}\n{var $storageVal = $note2 ?: \'2–6 °C\'}\n{var $storageText = str_starts_with($storageVal, \'Skladujte\') ? $storageVal : (\'Skladujte při \' . $storageVal)}\n{var $packerVal = $note3 ?: \'Fikko Market · adresa provozovny\'}\n{var $packerText = str_starts_with($packerVal, \'Balí\') ? $packerVal : (\'Balí: \' . $packerVal)}\n{var $finalPriceMinorFormatted = str_starts_with($finalPriceMinor, \',\') ? $finalPriceMinor : (\',\' . $finalPriceMinor)}\n\n<section class=\"fikko-fruit\">\n    <div class=\"product-title\">{$labelName}</div>\n    <div class=\"title-divider\"></div>\n\n    <div class=\"weight-col\">\n        <div>\n            <div class=\"meta-label\">Hmotnost</div>\n            <div class=\"meta-val\">{$weightVal}</div>\n        </div>\n        <div class=\"meta-item-spacing\">\n            <div class=\"meta-label\">Cena za 1 kg</div>\n            <div class=\"meta-val\">{$unitPriceVal}</div>\n        </div>\n    </div>\n\n    <div class=\"price-col\">\n        <div class=\"price-header-label\">Cena</div>\n        <div class=\"price-wrap\">\n            <div class=\"price-major\">{$finalPriceMajor}</div>\n            <div class=\"price-side\">\n                <div class=\"price-minor\">{$finalPriceMinorFormatted}</div>\n                <div class=\"price-currency\">{$currencySymbol}</div>\n            </div>\n        </div>\n    </div>\n\n    <div class=\"details-col\">\n        <div>Baleno dne: <b>{$packedDate}</b></div>\n        <div>Spotřebujte do: <b>{$expiryDate}</b></div>\n        <div>{$storageText}</div>\n        <div>Země původu: <b>{$countryName}</b></div>\n    </div>\n\n    <div class=\"barcode-col\">\n        <div n:if=\"$bars\" class=\"barcode-bars\">\n            <div n:foreach=\"$bars as $bar\" style=\"float:left;height:100%;background:{$bar[\'color\']|noescape};width:{$bar[\'width\']|noescape}\"></div>\n        </div>\n        <div class=\"barcode-ean\">{$eanText ?: \'2810001063137\'}</div>\n    </div>\n\n    <div class=\"footer-text\">{$packerText}</div>\n</section>\n', 1, 1),
(12, '2026-10-08 19:51:09', 'Fikko Cena Vel.2B Akce', 6, 133.00, 52.00, 'always', '<style>\r\n    @page { margin: 0; }\r\n    html, body { margin: 0; padding: 0; font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif; background: #fff; color: #111; -webkit-font-smoothing: antialiased; }\r\n    * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }\r\n\r\n    .fikko-vel2b-akce {\r\n        box-sizing: border-box;\r\n        position: relative;\r\n        width: 133mm;\r\n        height: 52mm;\r\n        border: 0.4mm dashed #111;\r\n        background: #fff;\r\n        color: #111;\r\n        overflow: hidden;\r\n        font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif;\r\n    }\r\n\r\n    /* Left logo / brand column (24mm x 52mm) */\r\n    .vel2b-logo-col {\r\n        position: absolute;\r\n        top: 0;\r\n        left: 0;\r\n        width: 24mm;\r\n        height: 52mm;\r\n        border-right: 0.4mm dashed #111;\r\n        text-align: center;\r\n        padding: 1.5mm 1mm;\r\n    }\r\n    .vel2b-logo-img {\r\n        width: 14mm;\r\n        height: 11mm;\r\n        object-fit: contain;\r\n        display: block;\r\n        margin: 0 auto;\r\n        filter: grayscale(1) contrast(1.15);\r\n    }\r\n    .vel2b-logo-divider {\r\n        width: 21mm;\r\n        margin: 1.5mm auto;\r\n        border-top: 0.3mm dashed #111;\r\n    }\r\n    .vel2b-brand-text {\r\n        margin-top: 10mm;\r\n        text-align: center;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 6mm;\r\n        line-height: 1.05;\r\n        color: #111;\r\n    }\r\n\r\n    /* Right main content column (109mm x 52mm) */\r\n    .vel2b-content-col {\r\n        position: absolute;\r\n        top: 0;\r\n        left: 27.5mm;\r\n        width: 103mm;\r\n        height: 52mm;\r\n        padding: 0.8mm 1mm 0.6mm 1mm;\r\n    }\r\n\r\n    /* 1. Product Name */\r\n    .vel2b-prod-name {\r\n        text-align: center;\r\n        font-size: 3.2mm;\r\n        font-weight: 400;\r\n        line-height: 1.1;\r\n        padding-top: 0.6mm;\r\n        height: 4mm;\r\n        overflow: hidden;\r\n        white-space: nowrap;\r\n    }\r\n\r\n    /* 2. Meta row */\r\n    .vel2b-meta-table {\r\n        width: 100%;\r\n        border-collapse: collapse;\r\n        margin-top: 0.5mm;\r\n    }\r\n    .vel2b-meta-left {\r\n        width: 50mm;\r\n        vertical-align: middle;\r\n        text-align: left;\r\n    }\r\n    .vel2b-meta-center {\r\n        vertical-align: middle;\r\n        text-align: center;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 2.6mm;\r\n        line-height: 1.1;\r\n        white-space: nowrap;\r\n    }\r\n    .vel2b-meta-right {\r\n        width: 8mm;\r\n    }\r\n\r\n    .vel2b-more-species {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 2.6mm;\r\n        line-height: 1.1;\r\n        margin-bottom: 0.4mm;\r\n    }\r\n    .vel2b-origin-row {\r\n        display: table;\r\n        white-space: nowrap;\r\n    }\r\n    .vel2b-origin-label-cell {\r\n        display: table-cell;\r\n        vertical-align: middle;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 2.2mm;\r\n        padding-right: 1mm;\r\n    }\r\n    .vel2b-origin-flag-cell {\r\n        display: table-cell;\r\n        vertical-align: middle;\r\n        width: 6.5mm;\r\n    }\r\n    .vel2b-origin-flag-img {\r\n        width: 5.5mm;\r\n        height: 5.5mm;\r\n        display: block;\r\n        border: 0.2mm solid #111;\r\n        border-radius: 50%;\r\n    }\r\n    .vel2b-origin-name-cell {\r\n        display: table-cell;\r\n        vertical-align: middle;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 2.2mm;\r\n        padding-left: 1mm;\r\n    }\r\n\r\n    /* 3. Main Price & Discount Table */\r\n    .vel2b-price-table {\r\n        width: 100%;\r\n        border-collapse: collapse;\r\n        margin-top: 0.8mm;\r\n    }\r\n    .vel2b-price-left {\r\n        width: 48mm;\r\n        vertical-align: middle;\r\n        text-align: right;\r\n        padding-right: 2.5mm;\r\n    }\r\n    .vel2b-price-right {\r\n        vertical-align: middle;\r\n        text-align: left;\r\n        padding-left: 2.5mm;\r\n    }\r\n\r\n    /* Nejnižší cena za 30 dní */\r\n    .vel2b-lowest-row {\r\n        white-space: nowrap;\r\n        text-align: right;\r\n    }\r\n    .vel2b-lowest-label {\r\n        display: inline-block;\r\n        vertical-align: middle;\r\n        font-size: 2.2mm;\r\n        line-height: 1.2;\r\n        letter-spacing: 0.04em;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        color: #111;\r\n        text-align: right;\r\n        margin-right: 1.5mm;\r\n    }\r\n    .vel2b-lowest-val-box {\r\n        position: relative;\r\n        display: inline-block;\r\n        vertical-align: middle;\r\n    }\r\n    .vel2b-lowest-val {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 5.5mm;\r\n        line-height: 1;\r\n        color: #111;\r\n    }\r\n    .vel2b-strike-wrap {\r\n        position: absolute;\r\n        left: 0;\r\n        top: 0;\r\n        width: 0;\r\n        height: 0;\r\n        overflow: visible;\r\n        display: inline-block;\r\n    }\r\n    .vel2b-strike-img {\r\n        position: absolute;\r\n        left: -1mm;\r\n        top: 3.3mm;\r\n        height: 2.8mm;\r\n    }\r\n\r\n    /* Ušetříte brush badge */\r\n    .vel2b-save-box {\r\n        position: relative;\r\n        width: 42mm;\r\n        height: 5.5mm;\r\n        margin-top: 1.5mm;\r\n        margin-left: auto;\r\n        transform: rotate(-1.2deg);\r\n        color: #fff;\r\n    }\r\n    .vel2b-save-brush {\r\n        position: absolute;\r\n        top: 0;\r\n        left: 0;\r\n        width: 42mm;\r\n        height: 5.5mm;\r\n        z-index: 0;\r\n    }\r\n    .vel2b-save-table {\r\n        position: relative;\r\n        z-index: 1;\r\n        width: 42mm;\r\n        height: 5.5mm;\r\n        border-collapse: collapse;\r\n        margin: 0 auto;\r\n    }\r\n    .vel2b-save-copy-cell {\r\n        vertical-align: middle;\r\n        text-align: right;\r\n        font-size: 2.4mm;\r\n        letter-spacing: 0.08em;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        white-space: nowrap;\r\n        padding-left: 2mm;\r\n        padding-bottom: 0.3mm;\r\n    }\r\n    .vel2b-save-val-cell {\r\n        vertical-align: middle;\r\n        text-align: center;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 4.6mm;\r\n        line-height: 1;\r\n        white-space: nowrap;\r\n        padding: 0 1.2mm;\r\n        padding-bottom: 0.3mm;\r\n    }\r\n\r\n    /* Naše cena */\r\n    .vel2b-our-label {\r\n        font-size: 2.2mm;\r\n        letter-spacing: 0.08em;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        margin-bottom: 0.4mm;\r\n        margin-left: 3mm;\r\n    }\r\n    .vel2b-main-price-box {\r\n        white-space: nowrap;\r\n    }\r\n    .vel2b-price-major {\r\n        display: inline-block;\r\n        vertical-align: top;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 21mm;\r\n        line-height: 0.85;\r\n    }\r\n    .vel2b-price-minor-col {\r\n        display: inline-block;\r\n        vertical-align: top;\r\n        text-align: left;\r\n        padding-top: 0.2mm;\r\n        margin-left: 0.8mm;\r\n    }\r\n    .vel2b-price-minor {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 10mm;\r\n        line-height: 0.9;\r\n    }\r\n    .vel2b-price-currency {\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 3.6mm;\r\n        line-height: 0.9;\r\n        white-space: nowrap;\r\n        margin-top: 0.4mm;\r\n    }\r\n\r\n    /* 4. Unit price row */\r\n    .vel2b-unit-price {\r\n        text-align: right;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 2.2mm;\r\n        white-space: nowrap;\r\n        padding-right: 1mm;\r\n        line-height: 1.1;\r\n        margin-top: 0.2mm;\r\n        margin-bottom: 0.2mm;\r\n    }\r\n\r\n    /* 5. Bottom row (Barcode, Note 3) */\r\n    .vel2b-bottom-box {\r\n        position: absolute;\r\n        left: 28mm;\r\n        right: 2.5mm;\r\n        bottom: 2.2mm;\r\n        width: 102.5mm;\r\n    }\r\n    .vel2b-bottom-table {\r\n        width: 100%;\r\n        border-collapse: collapse;\r\n    }\r\n    .vel2b-barcode-cell {\r\n        width: 48mm;\r\n        vertical-align: bottom;\r\n        text-align: left;\r\n    }\r\n    .vel2b-barcode-bars {\r\n        height: 5.2mm;\r\n        white-space: nowrap;\r\n        margin-bottom: 0.2mm;\r\n    }\r\n    .vel2b-barcode-bars > div {\r\n        float: left;\r\n        height: 100%;\r\n    }\r\n    .vel2b-barcode-ean {\r\n        font-size: 2.2mm;\r\n        font-weight: 600;\r\n        white-space: nowrap;\r\n        letter-spacing: 0.04em;\r\n        line-height: 1;\r\n        clear: both;\r\n    }\r\n    .vel2b-note3-cell {\r\n        vertical-align: bottom;\r\n        text-align: center;\r\n        font-family: Nunito, sans-serif;\r\n        font-weight: 900;\r\n        font-style: italic;\r\n        font-size: 2.6mm;\r\n        line-height: 1.15;\r\n        max-height: 5.5mm;\r\n        overflow: hidden;\r\n    }\r\n    .vel2b-bottom-spacer {\r\n        width: 10mm;\r\n    }\r\n\r\n    /* 3-digit price scaling */\r\n    .price-digits-3 .vel2b-price-major { font-size: 16mm; }\r\n    .price-digits-3 .vel2b-price-minor { font-size: 7.5mm; }\r\n    .price-digits-3 .vel2b-price-currency { font-size: 3.1mm; margin-top: 0.2mm; }\r\n    .price-digits-3 .vel2b-lowest-val { font-size: 4.8mm; }\r\n    .price-digits-3 .vel2b-price-left { width: 44mm; }\r\n</style>\r\n\r\n{var $vel2bClasses = ($priceDigits >= 3 ? \'price-digits-3\' : \'\')}\r\n{var $logoMarkup = \'<img class=\"vel2b-logo-img\" src=\"\' . $logoDataUri . \'\" alt=\"Fikko market\">\'}\r\n{var $flagMarkup = $flagIconDataUri ? \'<img class=\"vel2b-origin-flag-img\" src=\"\' . $flagIconDataUri . \'\" alt=\"\">\' : \'\'}\r\n{var $brushMarkup = \'<img class=\"vel2b-save-brush\" src=\"\' . $brushDataUri . \'\" alt=\"\">\'}\r\n{var $strikeWidth = (strlen($basePriceText) <= 4 ? \"18mm\" : (strlen($basePriceText) <= 5 ? \"23mm\" : (strlen($basePriceText) <= 6 ? \"28mm\" : \"34mm\")))}\r\n{var $strikeMarkup = \'<img class=\"vel2b-strike-img\" src=\"\' . $strikeSlashDataUri . \'\" style=\"width:\' . $strikeWidth . \'\" alt=\"\">\'}\r\n\r\n<div class=\"fikko-vel2b-akce {$vel2bClasses}\">\r\n    <div class=\"vel2b-logo-col\">\r\n        {$logoMarkup|noescape}\r\n        <div class=\"vel2b-logo-divider\"></div>\r\n        <div class=\"vel2b-brand-text\">\r\n            <div>Fikko</div>\r\n            <div>Cena</div>\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"vel2b-content-col\">\r\n        <div class=\"vel2b-prod-name\">{$labelName}</div>\r\n\r\n        <table class=\"vel2b-meta-table\" cellpadding=\"0\" cellspacing=\"0\">\r\n            <tr>\r\n                <td class=\"vel2b-meta-left\">\r\n                    <div n:if=\"$label && $label->is_more_species\" class=\"vel2b-more-species\">Více druhů</div>\r\n                    <div n:if=\"$country\" class=\"vel2b-origin-row\">\r\n                        <span class=\"vel2b-origin-label-cell\">Země původu:</span>\r\n                        <span class=\"vel2b-origin-flag-cell\">{$flagMarkup|noescape}</span>\r\n                        <span class=\"vel2b-origin-name-cell\">{$country->name}</span>\r\n                    </div>\r\n                </td>\r\n                <td class=\"vel2b-meta-center\">\r\n                    <div n:if=\"$note1\">{$note1}</div>\r\n                </td>\r\n                <td class=\"vel2b-meta-right\"></td>\r\n            </tr>\r\n        </table>\r\n\r\n        <table class=\"vel2b-price-table\" cellpadding=\"0\" cellspacing=\"0\">\r\n            <tr>\r\n                <td class=\"vel2b-price-left\">\r\n                    <div n:if=\"$isDiscounted && $basePrice > $finalPrice\" class=\"vel2b-lowest-row\">\r\n                        <span class=\"vel2b-lowest-label\">Nejnižší cena<br>za 30 dní</span>\r\n                        <div class=\"vel2b-lowest-val-box\">\r\n                            <span class=\"vel2b-lowest-val\">{$basePriceText} {$currencySymbol}</span>\r\n                            <span class=\"vel2b-strike-wrap\">{$strikeMarkup|noescape}</span>\r\n                        </div>\r\n                    </div>\r\n                    <div n:if=\"$isDiscounted && $saving > 0\" class=\"vel2b-save-box\">\r\n                        {$brushMarkup|noescape}\r\n                        <table class=\"vel2b-save-table\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\r\n                            <tr>\r\n                                <td class=\"vel2b-save-copy-cell\">UŠETŘÍTE</td>\r\n                                <td class=\"vel2b-save-val-cell\">{$savingText}&nbsp;{$currencySymbol}</td>\r\n                            </tr>\r\n                        </table>\r\n                    </div>\r\n                </td>\r\n\r\n                <td class=\"vel2b-price-right\">\r\n                    <div class=\"vel2b-our-label\">Naše cena</div>\r\n                    <div class=\"vel2b-main-price-box\">\r\n                        <span class=\"vel2b-price-major\">{$finalPriceMajor}</span>\r\n                        <div class=\"vel2b-price-minor-col\">\r\n                            <div class=\"vel2b-price-minor\">{$finalPriceMinor}</div>\r\n                            <div class=\"vel2b-price-currency\">{$currencySymbol} / 1 ks</div>\r\n                        </div>\r\n                    </div>\r\n                </td>\r\n            </tr>\r\n        </table>\r\n\r\n        <div n:if=\"$unit\" class=\"vel2b-unit-price\">\r\n            cena za {$unit->unitWeight}{$unit->unitShort} = {$unit->price|number:2,\',\',\' \'} {$currencySymbol}\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"vel2b-bottom-box\">\r\n        <table class=\"vel2b-bottom-table\" cellpadding=\"0\" cellspacing=\"0\">\r\n            <tr>\r\n                <td class=\"vel2b-barcode-cell\">\r\n                    <div n:if=\"$bars\" class=\"vel2b-barcode-bars\">\r\n                        <div n:foreach=\"$bars as $bar\" style=\"height:100%;background:{$bar[\'color\']|noescape};width:{$bar[\'width\']|noescape}\"></div>\r\n                    </div>\r\n                    <div class=\"vel2b-barcode-ean\">EAN: {$eanText}</div>\r\n                </td>\r\n                <td class=\"vel2b-note3-cell\">\r\n                    <div n:if=\"$note3 || $note2\">{$note3 ?: $note2}</div>\r\n                </td>\r\n                <td class=\"vel2b-bottom-spacer\"></td>\r\n            </tr>\r\n        </table>\r\n    </div>\r\n</div>\r\n', 1, 1),
(13, '2026-10-08 20:46:00', 'Fikko Cena Vel. 2 Akce', 7, 133.00, 38.00, 'always', '<style>\n    @page { margin: 0; }\n    html, body { margin: 0; padding: 0; font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif; background: #fff; color: #111; -webkit-font-smoothing: antialiased; }\n    * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n\n    .fikko-vel2-akce {\n        box-sizing: border-box;\n        position: relative;\n        width: 133mm;\n        height: 38mm;\n        border: 0.4mm dashed #111;\n        background: #fff;\n        color: #111;\n        overflow: hidden;\n        font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif;\n    }\n\n    /* Left logo / brand column (24mm x 38mm) */\n    .vel2-logo-col {\n        position: absolute;\n        top: 0;\n        left: 0;\n        width: 24mm;\n        height: 38mm;\n        border-right: 0.4mm dashed #111;\n        text-align: center;\n        padding: 1.5mm 1mm;\n    }\n    .vel2-logo-img {\n        width: 14mm;\n        height: 11mm;\n        object-fit: contain;\n        display: block;\n        margin: 0 auto;\n        filter: grayscale(1) contrast(1.15);\n    }\n    .vel2-logo-divider {\n        width: 100%;\n        margin: 1.2mm auto 1.2mm auto;\n        border-top: 0.3mm dashed #111;\n    }\n    .vel2-brand-text {\n        text-align: center;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 4.4mm;\n        line-height: 1.05;\n        color: #111;\n    }\n\n    /* Right main content column (109mm x 38mm) */\n    .vel2-content-col {\n        position: absolute;\n        top: 0;\n        left: 27.5mm;\n        width: 103mm;\n        height: 38mm;\n        padding: 0.8mm 1mm 0.6mm 1mm;\n    }\n\n    /* 1. Product Name */\n    .vel2-prod-name {\n        text-align: center;\n        font-size: 3.2mm;\n        font-weight: 400;\n        line-height: 1.1;\n        overflow: hidden;\n        white-space: nowrap;\n        height: 3.6mm;\n        padding-top: 0.2mm;\n    }\n\n    /* 2. Meta row (Origin, Note1, More species) */\n    .vel2-meta-table {\n        width: 100%;\n        border-collapse: collapse;\n        margin-top: 0.4mm;\n    }\n    .vel2-meta-left {\n        width: 50mm;\n        vertical-align: top;\n        text-align: left;\n    }\n    .vel2-meta-center {\n        vertical-align: top;\n        text-align: center;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.6mm;\n        line-height: 1.1;\n        white-space: nowrap;\n    }\n    .vel2-meta-right {\n        width: 10mm;\n    }\n\n    .vel2-more-species {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.6mm;\n        line-height: 1.1;\n        margin-bottom: 0.2mm;\n    }\n    .vel2-origin-row {\n        display: table;\n        white-space: nowrap;\n    }\n    .vel2-origin-label-cell {\n        display: table-cell;\n        vertical-align: middle;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.2mm;\n        padding-right: 1mm;\n    }\n    .vel2-origin-flag-cell {\n        display: table-cell;\n        vertical-align: middle;\n        width: 4.2mm;\n    }\n    .vel2-origin-flag-img {\n        width: 3.6mm;\n        height: 2.4mm;\n        display: block;\n        border: 0.2mm solid #111;\n    }\n    .vel2-origin-name-cell {\n        display: table-cell;\n        vertical-align: middle;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.2mm;\n        padding-left: 1mm;\n    }\n\n    /* 3. Main Price & Discount Table - NO vertical divider */\n    .vel2-price-table {\n        width: 100%;\n        border-collapse: collapse;\n        margin-top: 0.4mm;\n    }\n    .vel2-price-left {\n        width: 50mm;\n        vertical-align: middle;\n        text-align: center;\n        padding-right: 1.5mm;\n    }\n    .vel2-price-right {\n        vertical-align: middle;\n        text-align: left;\n        padding-left: 2mm;\n    }\n\n    /* Nejnižší cena za 30 dní */\n    .vel2-lowest-row {\n        white-space: nowrap;\n        text-align: center;\n    }\n    .vel2-lowest-label {\n        display: inline-block;\n        vertical-align: middle;\n        font-size: 2.2mm;\n        line-height: 1.2;\n        letter-spacing: 0.04em;\n        text-transform: uppercase;\n        font-weight: 700;\n        color: #111;\n        text-align: right;\n        margin-right: 1.5mm;\n    }\n    .vel2-lowest-val-box {\n        position: relative;\n        display: inline-block;\n        vertical-align: middle;\n    }\n    .vel2-lowest-val {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 5.5mm;\n        line-height: 1;\n        color: #111;\n    }\n    .vel2-strike-wrap {\n        position: absolute;\n        left: 0;\n        top: 0;\n        width: 0;\n        height: 0;\n        overflow: visible;\n        display: inline-block;\n    }\n    .vel2-strike-img {\n        position: absolute;\n        left: -1mm;\n        top: 3.0mm;\n        height: 2.8mm;\n    }\n\n    /* Ušetříte brush badge */\n    .vel2-save-box {\n        position: relative;\n        width: 44mm;\n        height: 4.8mm;\n        margin-top: 0.6mm;\n        margin-left: auto;\n        margin-right: auto;\n        transform: rotate(-1.2deg);\n        color: #fff;\n    }\n    .vel2-save-brush {\n        position: absolute;\n        top: 0;\n        left: 0;\n        width: 44mm;\n        height: 4.8mm;\n        z-index: 0;\n    }\n    .vel2-save-table {\n        position: relative;\n        z-index: 1;\n        width: 44mm;\n        height: 4.8mm;\n        border-collapse: collapse;\n        margin: 0 auto;\n    }\n    .vel2-save-copy-cell {\n        vertical-align: middle;\n        text-align: right;\n        font-size: 2.4mm;\n        letter-spacing: 0.08em;\n        text-transform: uppercase;\n        font-weight: 700;\n        white-space: nowrap;\n        padding-left: 2.5mm;\n        color: #fff;\n    }\n    .vel2-save-val-cell {\n        vertical-align: middle;\n        text-align: center;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 4.5mm;\n        line-height: 1;\n        white-space: nowrap;\n        padding: 0 1.5mm;\n        color: #fff;\n    }\n\n    /* Naše cena */\n    .vel2-our-label {\n        font-size: 2.2mm;\n        letter-spacing: 0.08em;\n        text-transform: uppercase;\n        font-weight: 700;\n        margin-bottom: 0.2mm;\n        margin-left: 6mm;\n    }\n    .vel2-main-price-box {\n        white-space: nowrap;\n        margin-left: 2mm;\n    }\n    .vel2-price-major {\n        display: inline-block;\n        vertical-align: top;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 16.5mm;\n        line-height: 0.85;\n    }\n    .vel2-price-minor-col {\n        display: inline-block;\n        vertical-align: top;\n        text-align: left;\n        padding-top: 0.3mm;\n        margin-left: 1mm;\n    }\n    .vel2-price-minor {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 8.5mm;\n        line-height: 0.9;\n    }\n    .vel2-price-currency {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 3.4mm;\n        line-height: 0.9;\n        white-space: nowrap;\n        margin-top: 0.3mm;\n    }\n\n    /* 4. Bottom row (EAN, Note 3, Unit price) - Absolute at bottom */\n    .vel2-bottom-box {\n        position: absolute;\n        left: 28mm;\n        right: 2.5mm;\n        bottom: 1.8mm;\n        width: 102.5mm;\n    }\n    .vel2-bottom-table {\n        width: 100%;\n        border-collapse: collapse;\n    }\n    .vel2-bottom-ean {\n        vertical-align: bottom;\n        text-align: left;\n        font-size: 2.2mm;\n        font-weight: 600;\n        white-space: nowrap;\n    }\n    .vel2-bottom-note3 {\n        vertical-align: bottom;\n        text-align: center;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.2mm;\n        line-height: 1.1;\n        white-space: nowrap;\n    }\n    .vel2-bottom-unit {\n        vertical-align: bottom;\n        text-align: right;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.2mm;\n        white-space: nowrap;\n    }\n\n    /* 3-digit price scaling (e.g. 199 Kč) */\n    .price-digits-3 .vel2-price-major { font-size: 14mm; }\n    .price-digits-3 .vel2-price-minor { font-size: 7.2mm; }\n    .price-digits-3 .vel2-price-currency { font-size: 2.9mm; margin-top: 0.2mm; }\n    .price-digits-3 .vel2-our-label { margin-left: 3mm; }\n    .price-digits-3 .vel2-main-price-box { margin-left: 0.5mm; }\n    .price-digits-3 .vel2-lowest-val { font-size: 4.8mm; }\n    .price-digits-3 .vel2-price-left { width: 48mm; }\n</style>\n\n{var $vel2Classes = ($priceDigits >= 3 ? \'price-digits-3\' : \'\')}\n{var $logoMarkup = \'<img class=\"vel2-logo-img\" src=\"\' . $logoDataUri . \'\" alt=\"Fikko market\">\'}\n{var $flagMarkup = $flagIconDataUri ? \'<img class=\"vel2-origin-flag-img\" src=\"\' . $flagIconDataUri . \'\" alt=\"\">\' : \'\'}\n{var $brushMarkup = \'<img class=\"vel2-save-brush\" src=\"\' . $brushDataUri . \'\" alt=\"\">\'}\n{var $strikeWidth = (strlen($basePriceText) <= 4 ? \'18mm\' : (strlen($basePriceText) <= 5 ? \'23mm\' : (strlen($basePriceText) <= 6 ? \'28mm\' : \'34mm\')))}\n{var $strikeMarkup = \'<img class=\"vel2-strike-img\" src=\"\' . $strikeSlashDataUri . \'\" style=\"width:\' . $strikeWidth . \'\" 