$isDiscounted && $saving > 0\" class=\"vel2-save-box\">\n                        {$brushMarkup|noescape}\n                        <table class=\"vel2-save-table\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                            <tr>\n                                <td class=\"vel2-save-copy-cell\">UŠETŘÍTE</td>\n                                <td class=\"vel2-save-val-cell\">{$savingText}&nbsp;{$currencySymbol}</td>\n                            </tr>\n                        </table>\n                    </div>\n                </td>\n\n                <td class=\"vel2-price-right\">\n                    <div class=\"vel2-our-label\">Naše cena</div>\n                    <div class=\"vel2-main-price-box\">\n                        <span class=\"vel2-price-major\">{$finalPriceMajor}</span>\n                        <div class=\"vel2-price-minor-col\">\n                            <div class=\"vel2-price-minor\">{$finalPriceMinor}</div>\n                            <div class=\"vel2-price-currency\">{$currencySymbol} / 1 ks</div>\n                        </div>\n                    </div>\n                </td>\n            </tr>\n        </table>\n    </div>\n\n    <div class=\"vel2-bottom-box\">\n        <table class=\"vel2-bottom-table\" cellpadding=\"0\" cellspacing=\"0\">\n            <tr>\n                <td class=\"vel2-bottom-ean\">EAN: {$eanText}</td>\n                <td class=\"vel2-bottom-note3\">\n                    <span n:if=\"$note3 || $note2\">{$note3 ?: $note2}</span>\n                </td>\n                <td class=\"vel2-bottom-unit\">\n                    <span n:if=\"$unit\">cena za {$unit->unitWeight}{$unit->unitShort} = {$unit->price|number:2,\',\',\' \'} {$currencySymbol}</span>\n                </td>\n            </tr>\n        </table>\n    </div>\n</div>\n', 1, 1),
(14, '2026-10-08 22:23:07', 'Fikko Cena – tem dải', 8, 150.00, 41.00, 'always', '<style>\n    @page { margin: 0; }\n    html, body { margin: 0; padding: 0; font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif; background: #fff; color: #111; -webkit-font-smoothing: antialiased; }\n    * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n\n    .fikko-pecivo {\n        box-sizing: border-box;\n        position: relative;\n        width: 150mm;\n        height: 41mm;\n        border: 0.4mm dashed #111;\n        background: #fff;\n        color: #111;\n        overflow: hidden;\n        font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif;\n    }\n\n    /* 1. Left Brand Column (32mm x 41mm) */\n    .pecivo-brand-col {\n        position: absolute;\n        top: 0;\n        left: 0;\n        width: 32mm;\n        height: 40.2mm;\n        border-right: 0.4mm dashed #111;\n        text-align: center;\n        padding: 0;\n    }\n    .pecivo-brand-table {\n        width: 100%;\n        height: 40.2mm;\n        border-collapse: collapse;\n    }\n    .pecivo-brand-cell {\n        vertical-align: middle;\n        text-align: center;\n    }\n    .pecivo-brand-text {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 7.5mm;\n        line-height: 1.05;\n        color: #111;\n    }\n\n    /* 2. Center Content Column (78mm x 41mm) */\n    .pecivo-center-col {\n        position: absolute;\n        top: 0;\n        left: 32mm;\n        width: 78mm;\n        height: 40.2mm;\n        padding: 0.6mm 2.5mm 0.6mm 2.5mm;\n    }\n\n    /* Top Box: Product Name and Subtitle */\n    .pecivo-top-box {\n        width: 73mm;\n        max-width: 73mm;\n        overflow: hidden;\n        white-space: nowrap;\n    }\n    .pecivo-prod-name {\n        font-size: 3.4mm;\n        font-weight: 700;\n        line-height: 1.15;\n        overflow: hidden;\n        white-space: nowrap;\n    }\n    .pecivo-prod-sub {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 3.2mm;\n        line-height: 1.15;\n        overflow: hidden;\n        white-space: nowrap;\n        margin-top: 0.1mm;\n    }\n\n    /* Middle Row: Notes (left) + Price (right) */\n    .pecivo-mid-table {\n        width: 73mm;\n        border-collapse: collapse;\n        margin-top: 0;\n    }\n    .pecivo-notes-cell {\n        width: 31mm;\n        vertical-align: middle;\n        text-align: left;\n        padding-right: 1mm;\n    }\n    .pecivo-note-row {\n        margin-bottom: 0.6mm;\n        white-space: nowrap;\n        line-height: 1.15;\n    }\n    .pecivo-note-tag {\n        font-size: 2.3mm;\n        letter-spacing: 0.06em;\n        text-transform: uppercase;\n        font-weight: 700;\n        color: #111;\n        display: inline-block;\n        margin-right: 1.2mm;\n    }\n    .pecivo-note-val {\n        font-size: 2.7mm;\n        font-weight: 700;\n        color: #111;\n        display: inline-block;\n    }\n\n    .pecivo-price-cell {\n        width: 42mm;\n        vertical-align: middle;\n        text-align: right;\n        white-space: nowrap;\n    }\n    .pecivo-price-wrap {\n        display: inline-block;\n        white-space: nowrap;\n    }\n    .pecivo-price-major {\n        display: inline-block;\n        vertical-align: top;\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 15mm;\n        line-height: 0.82;\n    }\n    .pecivo-price-minor-col {\n        display: inline-block;\n        vertical-align: top;\n        text-align: left;\n        margin-left: 0.8mm;\n    }\n    .pecivo-price-minor {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 8.5mm;\n        line-height: 0.9;\n    }\n    .pecivo-price-currency {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 4.8mm;\n        line-height: 0.9;\n        white-space: nowrap;\n        margin-top: 0.2mm;\n    }\n    .pecivo-unit-price {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2.3mm;\n        line-height: 1;\n        text-align: right;\n        margin-top: 0.2mm;\n        margin-bottom: 0.4mm;\n        white-space: nowrap;\n    }\n\n    /* Bottom Info Row (Origin, Snowflake badge, Barcode) */\n    .pecivo-bottom-box {\n        position: absolute;\n        left: 34.5mm;\n        bottom: 0.8mm;\n        width: 73mm;\n    }\n    .pecivo-bottom-table {\n        width: 100%;\n        border-collapse: collapse;\n    }\n    .pecivo-bottom-origin-cell {\n        vertical-align: middle;\n        text-align: left;\n        white-space: nowrap;\n        width: 25mm;\n    }\n    .pecivo-origin-flag {\n        width: 4.5mm;\n        height: 3mm;\n        display: inline-block;\n        vertical-align: middle;\n        border: 0.2mm solid #111;\n    }\n    .pecivo-origin-name {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2mm;\n        display: inline-block;\n        vertical-align: middle;\n        margin-left: 1mm;\n    }\n\n    .pecivo-bottom-badge-cell {\n        vertical-align: middle;\n        text-align: center;\n        white-space: nowrap;\n        width: 24mm;\n    }\n    .pecivo-defrost-badge {\n        display: inline-block;\n        vertical-align: middle;\n        border: 0.3mm solid #111;\n        border-radius: 1mm;\n        padding: 0.3mm 1mm;\n        white-space: nowrap;\n    }\n    .pecivo-snowflake-img {\n        width: 3.4mm;\n        height: 3.4mm;\n        display: inline-block;\n        vertical-align: middle;\n    }\n    .pecivo-defrost-text {\n        font-family: Nunito, sans-serif;\n        font-weight: 900;\n        font-style: italic;\n        font-size: 2mm;\n        display: inline-block;\n        vertical-align: middle;\n        margin-left: 0.8mm;\n    }\n\n    .pecivo-bottom-barcode-cell {\n        vertical-align: bottom;\n        text-align: right;\n        white-space: nowrap;\n        width: 24mm;\n    }\n    .pecivo-barcode-container {\n        display: inline-block;\n        text-align: center;\n        vertical-align: bottom;\n    }\n    .pecivo-barcode-bars {\n        height: 3.8mm;\n        margin-bottom: 0.2mm;\n        display: block;\n        overflow: hidden;\n    }\n    .pecivo-barcode-bars > div {\n        float: left;\n        height: 100%;\n    }\n    .pecivo-barcode-ean {\n        clear: both;\n        font-size: 1.6mm;\n        letter-spacing: 0.02em;\n        text-align: center;\n        line-height: 1.1;\n    }\n\n    /* 3. Right Column: Složení & Výrobce (40mm x 41mm) */\n    .pecivo-right-col {\n        position: absolute;\n        top: 0;\n        left: 110mm;\n        width: 40mm;\n        height: 40.2mm;\n        border-left: 0.4mm dashed #111;\n        padding: 0.8mm 2mm 0.6mm 2mm;\n        overflow: hidden;\n    }\n    .pecivo-ingredients-title {\n        font-size: 2.4mm;\n        letter-spacing: 0.08em;\n        text-transform: uppercase;\n        font-weight: 700;\n        color: #111;\n        margin-bottom: 0.3mm;\n    }\n    .pecivo-ingredients-text {\n        font-size: 2.0mm;\n        line-height: 1.15;\n        font-weight: 400;\n        height: 22mm;\n        overflow: hidden;\n    }\n    .pecivo-manufacturer-box {\n        position: absolute;\n        left: 0;\n        bottom: 0;\n        width: 39.6mm;\n        height: 11.5mm;\n        border-top: 0.25mm dashed #111;\n        padding: 0.5mm 2mm 0.4mm 2mm;\n        background: #fff;\n    }\n    .pecivo-manufacturer-title {\n        font-size: 1.8mm;\n        letter-spacing: 0.08em;\n        text-transform: uppercase;\n        font-weight: 700;\n        line-height: 1.1;\n    }\n    .pecivo-manufacturer-name {\n        font-size: 1.9mm;\n        line-height: 1.15;\n        font-weight: 700;\n    }\n    .pecivo-manufacturer-addr {\n        font-size: 1.8mm;\n        line-height: 1.15;\n        font-weight: 400;\n    }\n\n    /* Price scaling for 3+ digits */\n    .price-digits-3 .pecivo-price-major { font-size: 13mm; }\n    .price-digits-3 .pecivo-price-minor { font-size: 7.5mm; }\n    .price-digits-3 .pecivo-price-currency { font-size: 4.2mm; margin-top: 0.2mm; }\n    .price-digits-4 .pecivo-price-major { font-size: 10.5mm; }\n    .price-digits-4 .pecivo-price-minor { font-size: 6.2mm; }\n    .price-digits-4 .pecivo-price-currency { font-size: 3.5mm; margin-top: 0.1mm; }\n</style>\n\n{var $pecivoClasses = ($priceDigits >= 4 ? \'price-digits-4\' : ($priceDigits >= 3 ? \'price-digits-3\' : \'\'))}\n{var $flagMarkup = $flagIconDataUri ? \'<img class=\"pecivo-origin-flag\" src=\"\' . $flagIconDataUri . \'\" alt=\"\">\' : \'\'}\n{var $snowflakeMarkup = $snowflakeIconDataUri ? \'<img class=\"pecivo-snowflake-img\" src=\"\' . $snowflakeIconDataUri . \'\" alt=\"\">\' : \'\'}\n\n<div class=\"fikko-pecivo {$pecivoClasses}\">\n    <!-- 1. Left Brand Column -->\n    <div class=\"pecivo-brand-col\">\n        <table class=\"pecivo-brand-table\" cellpadding=\"0\" cellspacing=\"0\">\n            <tr>\n                <td class=\"pecivo-brand-cell\">\n                    <div class=\"pecivo-brand-text\">\n                        <div>Fikko</div>\n                        <div>Cena</div>\n                    </div>\n                </td>\n            </tr>\n        </table>\n    </div>\n\n    <!-- 2. Center Content Column -->\n    <div class=\"pecivo-center-col\">\n        <div class=\"pecivo-top-box\">\n            <div class=\"pecivo-prod-name\">{$labelName}</div>\n            <div n:if=\"($label && $label->is_more_species) || ($label && $label->sale_text) || $note3\" class=\"pecivo-prod-sub\">\n                {if $label && $label->is_more_species}\n                    Více druhů\n                {elseif $label && $label->sale_text}\n                    {$label->sale_text}\n                {elseif $note3}\n                    {$note3}\n                {/if}\n            </div>\n        </div>\n\n        <table class=\"pecivo-mid-table\" cellpadding=\"0\" cellspacing=\"0\">\n            <tr>\n                <td class=\"pecivo-notes-cell\">\n                    <div class=\"pecivo-note-row\">\n                        <span class=\"pecivo-note-tag\">Poznámka 1</span>\n                        <span class=\"pecivo-note-val\">{$note1 ?: \'\'}</span>\n                    </div>\n                    <div class=\"pecivo-note-row\">\n                        <span class=\"pecivo-note-tag\">Poznámka 2</span>\n                        <span class=\"pecivo-note-val\">{$note2 ?: \'\'}</span>\n                    </div>\n                </td>\n                <td class=\"pecivo-price-cell\">\n                    <div class=\"pecivo-price-wrap\">\n                        <span class=\"pecivo-price-major\">{$finalPriceMajor}</span>\n                        <div class=\"pecivo-price-minor-col\">\n                            <div class=\"pecivo-price-minor\">{$finalPriceMinor}</div>\n                            <div class=\"pecivo-price-currency\">{$currencySymbol} / 1 ks</div>\n                        </div>\n                    </div>\n                    <div n:if=\"$unit\" class=\"pecivo-unit-price\">\n                        cena za {$unit->unitWeight}{$unit->unitShort} = {$unit->price|number:2,\',\',\' \'} {$currencySymbol}\n                    </div>\n                </td>\n            </tr>\n        </table>\n    </div>\n\n    <!-- Bottom Bar (Center) -->\n    <div class=\"pecivo-bottom-box\">\n        <table class=\"pecivo-bottom-table\" cellpadding=\"0\" cellspacing=\"0\">\n            <tr>\n                <td class=\"pecivo-bottom-origin-cell\">\n                    <div n:if=\"$country\">\n                        {$flagMarkup|noescape}\n                        <span class=\"pecivo-origin-name\">{$country->name}</span>\n                    </div>\n                </td>\n                <td class=\"pecivo-bottom-badge-cell\">\n                    <div class=\"pecivo-defrost-badge\">\n                        {$snowflakeMarkup|noescape}\n                        <span class=\"pecivo-defrost-text\">Rozmrazeno</span>\n                    </div>\n                </td>\n                <td class=\"pecivo-bottom-barcode-cell\">\n                    <div class=\"pecivo-barcode-container\">\n                        <div n:if=\"$bars\" class=\"pecivo-barcode-bars\">\n                            <div n:foreach=\"$bars as $bar\" style=\"background:{$bar[\'color\']|noescape};width:{$bar[\'width\']|noescape}\"></div>\n                        </div>\n                        <div class=\"pecivo-barcode-ean\">{$eanText}</div>\n                    </div>\n                </td>\n            </tr>\n        </table>\n    </div>\n\n    <!-- 3. Right Column: Složení & Výrobce -->\n    <div class=\"pecivo-right-col\">\n        <div class=\"pecivo-ingredients-title\">Složení</div>\n        <div class=\"pecivo-ingredients-text\">\n            {if !$hideIngredients && $product && $product->ingredients}\n                {$product->ingredients|truncate:130}\n            {elseif !$hideIngredients}\n                Aqua, Sodium Laureth Sulfate, Cocamidopropyl Betaine, Sodium Chloride, Parfum.\n            {/if}\n        </div>\n\n        <div class=\"pecivo-manufacturer-box\">\n            <div class=\"pecivo-manufacturer-title\">Výrobce</div>\n            <div class=\"pecivo-manufacturer-name\">Fikko market s.r.o.</div>\n            <div class=\"pecivo-manufacturer-addr\">Hermanická 163/7, Praha 9</div>\n        </div>\n    </div>\n</div>\n', 1, 1)
